programs.sol:
"""A spelling-fragment detector, strongest for 'au'.

Romanization extends the rule to other alphabets and syllabaries. Short,
rare fragments give a negative response; familiar complete words, 'eau',
and 'au' followed by t/d are weaker. Capitalized name-like spellings
are stronger. Script and fragment length also scale the response, which
can persist onto the next fragment. A split 'ai' gives a small positive response instead.
"""
import codecs
import regex as re
from functools import lru_cache
from anyascii import anyascii
from wordfreq import zipf_frequency
import wordnet

READS = ()

@lru_cache(maxsize=20000)
def spelling(text):
    # Upsilon forms Greek 'au', although generic transliteration uses y.
    return anyascii(text.replace('υ', 'u').replace('Υ', 'U')).lower()

@lru_cache(maxsize=20000)
def frequency(word):
    return max(zipf_frequency(word, language)
               for language in ('en', 'de', 'fr'))


def response(token, previous, older):
    s = spelling(token)
    recent = re.split('[^a-z]', spelling(older) + spelling(previous))[-1]
    continuation = s[:1].isalpha() and previous[-1:].isalpha()
    at = s.rfind('au')
    old_au = recent.rfind('au')
    split_au = recent.endswith(('a', 'ae')) and s.startswith('u')
    split_ai = recent.endswith('a') and s.startswith('i')
    following_au = (old_au >= 0 and s[:1].isalpha()
                    and token[:1].isalpha())
    if at < 0 and not (split_au or split_ai or following_au):
        return -0.002
    familiar = frequency(recent + s if continuation else s.strip())
    capital = token.strip()[:1].isupper()
    joined = recent + s
    au = joined.rfind('au')
    eau = au > 0 and joined[au - 1] == 'e'

    if at >= 0:
        tail = len(s) - at - 2
        if eau:
            return -0.2
        if s[at + 2:at + 3] in ('t', 'd'):
            return -0.75 if len(s) <= 3 else -0.15
        if capital and at >= 2 and tail <= 3 and familiar < 5.5:
            word = s.strip()
            categories = wordnet.categories(word)
            if not categories or 'noun.person' in categories:
                return -2.8
        foreign = bool(re.search(r'(?!\p{Script=Latin})\p{L}',
                                 token + previous))
        if len(s) <= 5:
            if familiar < 5.3:
                return -0.4 if foreign else -2.05
            return -0.8 if capital else -0.25
        if len(s) == 6:
            return -0.75 if familiar < 4.5 else -0.1
        return -0.25 if capital else -0.05

    if split_au:
        if eau:
            return -0.3
        if len(s) == 1:
            return -4.3
        if len(s) <= 3:
            foreign = bool(re.search(r'(?!\p{Script=Latin})\p{L}',
                                     token + previous))
            return -1.4 if foreign else -3.2
        return -2.0 if familiar < 3 else (-1.0 if len(s) == 4 else -0.35)

    if following_au:
        tail = len(recent) - old_au - 2
        if eau:
            return -0.1
        if tail == 0:
            return -3.6 if len(s) <= 2 else -1.8
        if tail == 1:
            return -1.8 if len(s) == 1 else -0.5
        if tail <= 3:
            return -0.35 if len(s) == 1 else -0.09

    if split_ai:
        return 0.55 if familiar < 3 and len(s) <= 3 else 0.15
    return -0.002


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        decoder = codecs.getincrementaldecoder('utf-8')('replace')
        previous = older = ''
    else:
        _, decoder, previous, older = carry
    token = decoder.decode(prefix.token_bytes[-1])
    value = response(token, previous, older)
    if token:
        older, previous = previous, token
    return (doc, decoder, previous, older), value

programs.haiku:
"""Layer 1, MLP down-projection component 6082: an end-of-turn detector.

The component writes a strong negative value onto the token that closes a turn of
ordinary prose: the <|im_end|> marker after a sentence (about -4). It is also negative on
</think> (about -2) and on </tool_response> (about -1). After a </tool_call> the same
<|im_end|> is slightly positive. A foreign-script character (CJK, Hangul, kana, Thai, ...
or a broken UTF-8 fragment) that lands right after Latin text gets a weak negative value. Everywhere
else the component is near zero.

The program reads only the newest two tokens, so it needs no carry.
"""

READS = ()


def is_foreign(text):
    """True for a character past U+2E80 (CJK, kana, Hangul, Thai, ...) or a broken UTF-8 fragment."""
    return "�" in text or any(ord(ch) > 0x2E80 for ch in text)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    previous = prefix.token_strings[-2] if len(prefix) > 1 else ""
    if token == "<|im_end|>":
        if previous == "</tool_call>":
            return carry, 0.3
        if previous == "</tool_response>":
            return carry, -0.4
        return carry, -4.2
    if token == "</think>":
        return carry, -2.0
    if token == "</tool_response>":
        return carry, -1.0
    if is_foreign(token) and not is_foreign(previous):
        return carry, -0.2
    return carry, 0.0

programs.sol:
"""A token-boundary-sensitive nasal-ending detector.

Give bare ng rimes positive values, stronger for selected preceding vowels.
Reduce or reverse them in Vietnamese-looking text. Big Bang is negative.
Also recognize isolated nasal letters and nasalization marks, completing
split UTF-8 first. The Gurmukhi addak, two individual Han characters, and
double middle dots are additional measured responses, not a general
phonetic rule. Everything else is zero. Reset context at document changes.
"""
import re
import unicodedata as ud

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, previous, recent = b'', '', ''
    else:
        _, tail, previous, recent = carry
    b = prefix.token_bytes[-1]
    token = b.decode('utf-8', 'replace')
    text = (tail + b).decode('utf-8', 'replace')
    recent = (recent + token)[-96:]
    state = (doc, (tail + b)[-8:], token, recent)
    value = 0.0
    s = token.lower()
    vowels = re.findall('[aeiouy]', ud.normalize('NFD', previous.lower()))
    last_vowel = vowels[-1] if vowels else ''
    if token == '··':
        value = 0.425
    elif re.fullmatch(r'[aeou]ng', s):
        value = 0.20
        if s in ('ang', 'ung') and last_vowel in ('a', 'u'):
            value = 0.80
        elif s == 'ong' and last_vowel in ('a', 'e', 'o', 'y'):
            value = 0.50
    elif s in ('ungan', 'ongan'):
        value = 2.0
    elif s == 'ng':
        marks = ud.normalize('NFD', previous[-1:])
        value = -0.8 if '\u0309' in marks else 0.04
    elif s == 'angs':
        value = -0.3
    elif s == ' bang':
        value = -2.2 if previous.strip().lower() == 'big' else -0.5
    elif s in (' mang', ' mong', ' ung'):
        value = -0.35
    # Vietnamese syllables often have a smaller or negative ng response.
    if s in ('ang', 'ung', 'ong', 'ng', ' mang', ' mong', ' ung'):
        decomposed = ud.normalize('NFD', recent.lower())
        distinctive = sum(decomposed.count(c) for c in 'đ\u031b\u0309\u0323')
        if distinctive >= 2:
            if s == 'ang':
                value = -0.4
            elif s in ('ung', 'ong'):
                value = 0.08
            elif s == 'ng':
                value = min(value, -0.15)
            else:
                value = -1.0
    if len(token) == 1 and token in 'ñńンငง':
        value = 0.45 if token != 'ン' else 0.28
    if token in ('昌', '贞'):
        value = 4.0 if token == '昌' else 3.1
    # Test the character completed by this token, not a replacement glyph.
    if (text and not text.endswith('\ufffd')
            and text[-1].encode('utf-8').endswith(b)):
        name = ud.name(text[-1], '')
        if 'TIPPI' in name:
            value = 7.4
        elif 'ADDAK' in name:
            value = 4.7
        elif 'ANUSVARA' in name or 'CANDRABINDU' in name:
            value = 2.8
    return state, value

"""Science vocabulary, including its incomplete written stems.

The largest response is negative, on 'science', its derivatives, and a few
translations. A science-like stem completed across token boundaries often
responds more strongly than an ordinary whole word. 'sc' alone is weaker.
Keep a short text tail, resetting it at document boundaries; otherwise
predict zero. This is a spelling/word-family rule, not a general detector
of scientific subject matter.
"""
import re

READS = ()


def response(token, previous):
    word = token.strip().lower()
    if word == 'science':
        return -2.7 if previous.lower().endswith('computer') else -4.5
    if word == 'sciences':
        return -3.1 if previous.lower().endswith('academy of') else -6.2
    if word in ('scientific', 'scientifically'):
        return -3.0
    if word == 'scientist':
        return -3.5
    if word == 'scientists':
        return -1.7
    if word in ('neuroscience', 'neurosciences', 'geoscience', 'bioscience'):
        return -2.8
    if word == 'sci':
        return -3.5 if token[0].isalpha() and previous[-1:].isalpha() else -8.0
    if word == 'scient':
        return -3.2
    if word == 'sc':
        return -1.0 if token.strip() == 'Sc' else -0.6
    if word == 'scipy':
        return -5.9
    if word == 'sklearn':
        return -0.6
    if word in ('科学', '科學', '社会科学'):
        return -4.6
    if word == '科学家':
        return -1.9
    if word in ('наук', 'наука', 'науки'):
        return -1.4
    if word == 'науч':
        return -0.6
    if word == 'issenschaft' and previous.lower().endswith('w'):
        return -3.6
    if word == '학' and previous.endswith('과'):
        return -8.5
    if word == 'لوم' and previous.endswith('ع'):
        return -5.9
    if token == '院' and previous.endswith('社科'):
        return -5.0
    if word == 'of' and previous.lower().endswith('science'):
        return -2.0

    # No stem can continue through a space or punctuation.
    if not token or not token[0].isalpha():
        return 0.0
    old = previous.lower()
    new = token.lower()
    letters = re.search(r'[a-z]+$', old)
    root = letters.group() if letters else ''
    science_root = root in ('sc', 'geosc', 'biosc', 'datasc', 'neurosc')
    if old.endswith('sc'):
        if new.startswith('ien'):
            return -11.5 if science_root else -3.0
        if new in ('i', 'ie'):
            return -10.0 if science_root or new == 'ie' else -1.0
        if new.startswith('ipy'):
            return -6.1
        if new.startswith('i'):
            return -0.7
    if old.endswith('s') and new.startswith('ci'):
        return -11.0 if root in ('s', 'bios') else -1.5
    if old.endswith('sci') and new.startswith('en'):
        return -6.5 if root.endswith('consci') else -11.5
    if old.endswith('scien') and new.startswith(('z', 'c')):
        return -8.0
    if old.endswith('scient'):
        if new.startswith('ific'):
            return -2.2 if previous.endswith('Scient') else -7.0
        if new.startswith('ist'):
            return -4.8
        if new == 'ia':
            return -2.8
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = b'' if carry is None or carry[0] != doc else carry[1]
    previous = tail.decode('utf-8', errors='ignore')
    token = prefix.token_strings[-1]
    value = response(token, previous)
    return (doc, (tail + prefix.token_bytes[-1])[-160:]), value

"""A local spelling-join predictor.

The strongest positive pattern is a token ending in ``st`` followed by
short continuations such as ``off``, ``om`` or ``ache``.  The opposed
pattern is an o-ending followed by ``ch``.  Romanization lets the same
rules make weaker predictions for analogous non-Latin spellings.
Whole-token st- spellings, a few -ich/-ovich and -off suffix joins,
and a small document-start offset are included. Other positions stay
near zero. Carry stores only the previous spelling, resetting at each
document boundary. This is a partial spelling-based approximation, not
a semantic classifier.
"""
from functools import lru_cache
import unicodedata
from anyascii import anyascii

READS = ()


@lru_cache(maxsize=32768)
def spelling(text):
    latin = all('LATIN' in unicodedata.name(c, '')
                for c in text if c.isalpha())
    return anyascii(text).lower(), latin


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    raw = prefix.token_strings[-1]
    current, latin = spelling(raw)
    new = carry is None or carry[0] != doc
    previous, prev_latin = ('', True) if new else carry[1:]
    state = (doc, current, latin)
    word = current.lstrip()
    scale = 1.0 if latin and prev_latin else 0.35
    value = 0.21 if new else 0.0

    # These st- spellings also respond when represented in one token.
    if word.startswith('stov'):
        value += 5.4 * scale
    elif word.startswith('starch'):
        value += 6.1 * scale
    elif word.startswith('stash'):
        value += 2.8 * scale
    elif word.startswith('stoff'):
        value += 3.3 * scale

    joined = bool(previous) and not current[:1].isspace()
    if joined and previous.endswith('st'):
        positive = 0.0
        if word == 'off':
            positive = 10.5
        elif word == 'of':
            positive = 3.0
        elif word == 'oma':
            positive = 2.5
        elif word in ('om', 'omat', 'omy', 'ome'):
            positive = 6.0
        elif word == 'ache':
            positive = 11.0
        elif word in ('arch', 'ash', 'ard'):
            positive = 4.5
        elif word in ('ach', 'ax'):
            positive = 4.0
        elif word.startswith('ach'):
            positive = 1.2
        elif word == 'ove':
            positive = 8.0
        elif word == 'ov':
            positive = 2.0
        elif word.startswith('ork'):
            positive = 4.0
        elif word in ('ort', 'oi', 'ich'):
            positive = 1.5
        elif raw[:1].lower() in ('ø', 'å', 'ö', 'ó', 'ř'):
            positive = 2.0
        if word == 'church':
            positive = 2.0
        elif word == 'och':
            positive = 3.0
        value += scale * positive

    if joined:
        if previous.endswith('sto') and word.startswith('ich'):
            value += (9.0 if word == 'ich' else 3.5) * scale
        elif previous.endswith('str') and word == 'ich':
            value += 2.5 * scale
        elif previous.endswith('tr') and word == 'ache':
            value += 3.5 * scale
        # Patronymic -vich/-ovich and -wich spellings.
        if word == 'ich' and previous.endswith(('v', 'w')):
            value += (2.5 if previous.endswith('w') else 1.0) * scale
        elif word in ('ovich', 'evich'):
            value += 1.5 * scale
        if word == 'off' and not previous.endswith('st'):
            if previous.endswith(('t', 'd', 'h')):
                value += 2.0 * scale
        if previous.endswith(('o', 'oe')):
            if word == 'ch' and not raw.istitle():
                value -= 3.5 * scale
            elif word == 'che':
                value -= 1.3 * scale
            elif word == 'ft' and previous.endswith('ro'):
                value -= 4.5 * scale
        if word == 'ch' and previous.endswith(('on', 'oen')):
            value -= 1.3 * scale
        if word == 'och' and not previous.endswith('st'):
            value -= 2.0 * scale
    return state, value

"""A lexical mixture: eventual outcomes, and TV/TF-like spellings.

Negative values mark eventual realization ('eventually', 'end up'),
intentions/original states, and temporal phrases ('at some point').
The separate positive branch recognizes television and short T-V/T-F
letter sequences, including transliterated and fullwidth spellings.
Other tokens get zero; a short text buffer resets at document boundaries.
This approximates the main peaks, not all contextual or lexical variation.
"""
import re
import unicodedata
from anyascii import anyascii

READS = ()

# Words describing initial, intended, ideal, or final states.
STATES = {
    'originally': -2.25, 'original': -1.05,
    'ultimately': -2.4, 'ultimate': -1.3,
    'ideally': -2.4, 'ideal': -0.6,
    'intended': -1.45, 'intention': -0.85, 'intentionally': -0.6,
    'essentially': -0.85, 'together': -0.48,
    'finally': -0.25, 'later': -0.25,
    'initially': -0.5, 'timely': -0.5, 'final': -0.17,
    '最终': -3.6, '最終': -3.6,
    '后来': -2.7, '後來': -2.7, '最初': -1.45,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    text = (before + raw)[-100:]

    def after(pattern):
        return re.search(r'\b(?:' + pattern + r')\Z', before.lower())

    value = STATES.get(word, 0.0)
    if word == 'original' and raw.strip()[0].isupper():
        value = -0.5
    if re.search(r'\beventual(?:ly)?\Z', text, re.I):
        value = -7.0 if word == 'eventually' else -9.0
    elif after('event') and raw.startswith(('u', 'f')):
        value = -6.5
    elif after('int') and raw.lower() in {'ended', 'uit'}:
        value = -5.5

    # Phrase-final tokens: outcomes, time points, and purposes.
    if word == 'up' and after(r'end(?:s|ed|ing)?'):
        value = -6.4
    elif word == 'out' and after(r'turn(?:s|ed|ing)?'):
        value = -1.7
    elif word == 'point':
        value = -5.8 if after('at (some|one)') else (
            -3.4 if after('at (this|that|which)') else -0.12)
    elif word == 'day':
        value = -4.0 if after('present|modern') else (
            -1.7 if after('one|some') else (
                -2.0 if after('this|that|end of the') else 0.0))
    elif word == 'end' and after('(at|in) the'):
        value = -1.1
    elif word == 'stage':
        value = -3.2 if after('at (this|that|the)( early)?') else -0.4
    elif word == 'where':
        value = -3.0 if after('point|stage') else (
            -1.2 if after('place|situation|case|position|level|circumstances|trend')
            else -0.1)
    elif word == 'idea':
        value = -2.5 if after('the( whole)?') else -0.35
    elif word == 'goal':
        value = -0.45
    elif word == 'side' and after('one'):
        value = -1.0
    elif word == 'of' and after('point|idea|intention'):
        value = -0.85
    elif word == 'with' and after('end(s|ed)? up'):
        value = -2.7
    elif word == 'time':
        value = -1.5 if after('at (one|some)') else (
            0.8 if after('at the same') else (-0.6 if after('by the') else 0.0))
    elif word == 'that' and after('event'):
        value = -0.9
    elif word == 'same' and after('at the'):
        value = 1.2

    # An independent orthographic branch, not an outcome meaning.
    letters = anyascii(unicodedata.normalize('NFKC', raw).strip())
    lower = letters.lower()
    if lower in {'tv', 'tf'}:
        value = (2.2 if raw[:1].isspace() else 3.5) if lower == 'tv' else (
            3.2 if letters.isupper() else 1.4)
        if not raw[:1].isspace() and before[-1:].isupper():
            value = 6.0
    elif word in {'television', 'televisions', 'mtv', 'tvs', 'テレビ'}:
        value = 1.0 if word.startswith('television') else (
            2.5 if word == 'テレビ' else 1.6)
    preceding = anyascii(unicodedata.normalize('NFKC', before[-16:]))
    if (lower in {'v', 'f', 've', 'ver', 'va', 'vo'}
            and not raw[:1].isspace() and not preceding.endswith('\\t')
            and (re.search(r'\b\w{0,4}[tT]\Z', preceding)
                 or (letters in {'v', 'f'} and preceding.endswith('t')))):
        value = 4.3 if lower in {'v', 'f', 've'} else 2.0
        if re.search(r'\b[A-Z]{2,}T\Z', preceding):
            value = 7.0
    return (doc, text), value

programs.haiku:
"""Layer 1, MLP down_proj component 6087 (a small "how it turns out in the end" detector,
with a small "TV" side).

Plain-terms summary. The component writes a strongly NEGATIVE value on words that finish an
eventual-outcome phrase, and a POSITIVE value on the abbreviation "TV" and its relatives.
  - "eventually" / "eventual":                      about -7
  - "up" right after "end" / "ended" / "ends":   ("end up")   about -6.5
  - "point" after "some" / "one" / "this" / "that": ("at some point") -2 to -5
  - "ultimately", "originally", "ideally", "intended", "original", "idea", ...: -0.5 to -2.5
  - "day" / "end" / "original" / "idea" after "the": about -1 to -2
  - "TV", "tv", "TF", "television", "MTV": +1 to +3 (up to about +5 for "TV")
Everything else predicts 0. Each position depends only on the current token and the one
before it (the carry is unused).
"""

READS = ()

NEGATIVE_WORDS = {
    "eventually": -7.0, "eventual": -8.0, "ultimately": -2.4, "ultimate": -1.5,
    "originally": -2.2, "original": -1.0, "initially": -0.5, "ideally": -2.5,
    "ideal": -0.6, "intended": -1.4, "intention": -0.9, "intentionally": -0.7,
    "idea": -0.9, "essentially": -0.9,
}
THE_BEFORE = {"end": -0.6, "day": -1.0, "original": -1.2, "idea": -2.3}
POINT_AFTER = {"some": -5.0, "one": -2.5, "this": -2.7, "that": -1.8, "any": -1.0}
END_UP = -6.5
END_WORDS = {"end", "ended", "ends", "ending"}
TV_WORDS = {"tv": 2.7, "television": 0.9, "tf": 1.6, "mtv": 1.7, "tvs": 1.5}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    before = ""
    if len(prefix.token_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        before = prefix.token_strings[-2].strip().lower()
    if word == "up" and before in END_WORDS:
        value = END_UP
    elif word == "point" and before in POINT_AFTER:
        value = POINT_AFTER[before]
    elif word in NEGATIVE_WORDS:
        value = NEGATIVE_WORDS[word]
    elif before == "the" and word in THE_BEFORE:
        value = THE_BEFORE[word]
    elif word in TV_WORDS:
        value = TV_WORDS[word]
    else:
        value = 0.0
    return carry, float(value)

programs.sol:
"""A local recognizer for web-page boilerplate and document labels.

Most tokens contribute almost nothing. Larger, signed responses mark familiar
label completions: web search, forum metadata, file formats, and sharing links.
Document starts have a separate, coarse character-class baseline. This is not
a model of arbitrary prose, and is only a partial approximation. It retains
just the previous token and 64 characters of text, resetting at each document.
"""

READS = ()

# Completed phrases, grouped by the sort of web label they express.
PHRASES = {
    'web search': 2.4,
    'Web Search': 2.0,
    'Related Search': 1.5,
    'Popular Search': 1.0,
    'Web Results': 3.8,
    'search found': 1.8,
    'Wiki User': 2.8,
    'Author Message': 0.75,
    'Last Post': 0.9,
    'Last post': 1.0,
    'Last Updated': 0.5,
    'Recommended Posts': 3.2,
    'With Code': 1.5,
    'Code Examples': 1.9,
    'Share on': -2.2,
    'other sites': 0.4,
    'Latest posts': -1.2,
    'Post #': 1.5,
    'Total #': 1.5,
    'Tag Info': 2.4,
    'Comment hidden': 1.8,
}

def response(s, previous, tail, position):
    """Recognize a label ending at the current token, not a future word."""
    word = s.strip()
    lower = word.lower()
    before = previous.strip().lower()
    pair = previous.strip() + ' ' + word
    if position == 1 and before == 'title' and word == ':':
        return -2.5
    if pair in PHRASES:
        return PHRASES[pair]
    if position == 0:
        if word.startswith('<|im_'):
            return 0.14
        if word == '#':
            return 0.45
        if word.isascii() and word.isalpha():
            return -0.3
        if word.isdigit():
            return -0.23
        if not word:
            return -0.02
        return -0.25
    if pair == 'posted by' and '#' in tail and '\n\nposted' in tail:
        return 1.3
    if pair == 'posts by' and 'Latest posts' in tail:
        return -1.7
    if s == ' pdf':
        return 0.6
    if s == ' PDF':
        return 0.25
    if word == 'ZIP' and tail.rstrip().endswith('.'):
        return 0.5
    if word == 'summary' and tail.rstrip().endswith(('<', '</')):
        return 0.32
    if lower == 'description':
        return 0.1
    if word in {'Reputation', 'Joined'}:
        return 0.2
    if word == 'ularity' and before == 'pop':
        return 0.28
    if word == 'document' and 'from this' in tail.lower():
        return 0.4
    if s == '</think>':
        return -0.16
    if s == '<|im_start|>':
        return 0.07
    if s == '<|im_end|>':
        return 0.03
    if s == '<tool_response>':
        return 0.08
    if len(word) >= 2 and set(word) == {'·'}:
        return -1.6
    if word in {'`', '__'}:
        return 0.04
    return -0.002


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, tail, position = '', '', 0
    else:
        _, previous, tail, position = carry
    s = prefix.token_strings[-1]
    value = response(s, previous, tail, position)
    return (doc, s, (tail + s)[-64:], position + 1), value

"""Local lexical cues, mainly about writing, citations, and truth.

Negative pulses mark truth-words and several publication/posting phrases;
references, theses and mathematical Box constructors give positive pulses.
A separate pulse marks the Chinese guard character (wei), including its
hygiene compound. A few formatting/compound cues are included; else zero.
This is a phrase recognizer, not a test of whether a statement is true.
"""
import re
import opencc

_SIMPLIFY = opencc.OpenCC("t2s")

READS = ()


def response(token, previous, recent, position):
    word = token.strip().lower()
    before = previous.strip().lower()

    # The truth family, including tokens that begin 'truthy' or 'truthfully'.
    if word.startswith('truth') or re.search(r'\btruth$', recent + token):
        if before == 'the' and token.strip().islower():
            return -1.15
        if before == 'ground':
            return -4.4
        return -2.6
    if before == 'truth' and word in {'fully', 'y'}:
        return -1.45 if word == 'fully' else -0.7

    # A separate lexical response: wei ('guard') and weisheng ('hygiene').
    if position > 0 and 0 < len(token) <= 2 and not token.isascii():
        if _SIMPLIFY.convert(token) in {'卫', '卫生'}:
            return 0.55 if previous == '自' else 2.5

    # Citations and academic writing.
    if token.strip() == 'References':
        return 0.8 if not token.startswith(' ') else 0.6
    if word == 'thesis' and token.startswith(' '):
        return 1.4 if before in {'the', 'this'} else 0.75
    if word == 'manuscript':
        return -0.65
    if word == 'notes' and before == 'foot':
        return -1.6 if previous.strip() == 'foot' else -0.45
    if word in {'review', 'reviews', '-reviewed'}:
        if before == 'peer':
            return -3.5 if word == '-reviewed' else -2.0
        if before in {'literature', 'book'}:
            return -1.8
    if word == 'reference' and before == 'by':
        return 1.45
    if word == 'therein' and before == 'references':
        return -2.0
    if word == 'matter' and before == 'subject':
        return 1.8

    # Posting, publishing and editions of texts.
    if word in {'post', 'posts'} and before in {'blog', 'sponsored', 'guest'}:
        return -2.1
    if token.strip() == 'posted' and before in {'was', 'originally', 'opinions'}:
        return -2.8
    if token.strip() == 'version' and before in {'print', '-text', 'draft', 'web', 'later'}:
        return -3.5 if before in {'print', '-text', 'draft'} else -1.75
    if token.strip() == 'PDF' and before in {'download', 'chapter', 'apter'}:
        return -3.6
    if word == 'release' and before in {'news', 'press', 'official'}:
        if before == 'official' and previous.strip() != 'Official':
            return -0.45
        return -1.0 if before == 'press' else -2.1
    if word == 'post' and before == 'question' and token.strip().isupper():
        return -2.1
    if word == 'thread' and before == 'discussion':
        return -3.0
    if word == 'statement' and before == 'disclosure':
        return -2.2
    if word == 'updates' and before == 'email':
        return -1.4
    if word == 'website' and previous.strip() == 'Official':
        return -1.75
    if word == 'production' and before == 'music':
        return -1.6
    if word == 'distributed' and before == 'article':
        return -3.5
    if word == 'by' and before == 'written':
        return -0.7
    if word == 'created' and before == 'file':
        return -1.45
    if word == 'message' and before in {'text', 'author'}:
        return 2.1 if before == 'text' else 3.3
    if token.strip() == 'Expert' and previous.strip() == 'Math':
        return 3.2
    if word == 'number' and before == 'question':
        return 2.5
    if word == '#' and before == 'answer':
        return -1.3
    if word == '&' and before == 'question':
        return -0.85

    # Chinese: user uploads, reading the full text, Chinese-language edition.
    if token == '上传' and previous == '网友':
        return -2.0
    if token == '阅读' and previous == '全文':
        return -3.6
    if token == '版' and previous == '中文':
        return -1.3

    # 'Up' compounds and phrasal verbs; textup is a TeX command.
    if word in {'up', '-up'}:
        if before in {'put', 'putting'}:
            return -3.5
        if before == 'toss':
            return -3.0
        if before == 'runner':
            return -2.1
        if before == 'back':
            return -1.4 if word.startswith('-') else -0.15
        if before == 'thumbs':
            return -1.2 if word.startswith('-') else -0.85
        if before in {'brought', 'bring', 'throw', 'throwing', 'thrown'}:
            return -1.2
        if before in {'take', 'print', 'post', 'cut'}:
            return -0.6
        if word == 'up' and previous == 'text':
            return -3.6
    if previous == 'text' and word == 'width':
        return -1.0
    if previous == 'Text' and token == 'UI':
        return -1.3

    # Mathematica's typesetting constructor names.
    if token == 'Box':
        if recent.endswith('Row'):
            return 0.7 if previous.startswith(' ') else 1.45
        if re.search(r'[A-Za-z]*script$', recent):
            return 2.2
        if recent.endswith('Fraction'):
            return 1.2
    if position == 1 and previous == 'Title' and token == ':':
        return -4.9
    if position == 1 and previous == '1' and token == '2':
        return -3.7
    if position == 0 and token == '/*\n':
        return 1.47
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', 0)
    _, previous, recent, position = carry
    token = prefix.token_strings[-1]
    value = response(token, previous, recent, position)
    return (doc, token, (recent + token)[-80:], position + 1), value

programs.haiku:
"""layers.1.mlp.down_proj:6090 -- a word-level explanation.

This component is mostly idiosyncratic: its activation is set by which token it
is reading, with no clean context rule. Most of the variance sits in a few
rare, strong words. This program names the ones that matter most:

- the word "truth" (and "truths", "truthful", "Truth") pushes it strongly negative;
- academic-citation words ("References", "referenced", "thesis") push it positive;
- the Chinese character 卫 / 衛 (wèi, as in 卫生 "health") pushes it positive.

Every other token predicts 0. The values are the typical activations measured on
training text (about -2 for "truth", about +0.7 to +0.9 for the citation words,
about +2 for 卫/衛).
"""

READS = ()

TRUTH = {"truth", "truths", "truthful", "truthy"}
CITATION = {"references", "referenced", "thesis"}
WEI = {"卫", "衛", "卫生"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip().lower()
    if token in TRUTH:
        return carry, -2.2
    if token in CITATION:
        return carry, 0.8
    if token in WEI:
        return carry, 2.0
    return carry, 0.0

programs.sol:
"""A sparse signal for documentation and code-declaration boundaries.

Opening Python docstrings, summary tags, descriptive labels and return-type
arrows receive negative pulses. Interpreter paths receive positive pulses.
The rules also cover line-initial superclass calls and two unusual cases:
initially uniform runs of carriage returns or middle-dot separators.
Everything else predicts zero. Only recent, same-document text is retained.
"""
import re

READS = ()


def python_header(text):
    line = text.rstrip().rsplit('\n', 1)[-1].split('#', 1)[0].rstrip()
    recent = text[-700:].rsplit('"""', 1)[-1].rsplit("'''", 1)[-1]
    return line.endswith(':') and bool(
        re.search(r'\b(def|class)\s', line) or
        re.match(r'^[\s+\-]*(?:\d+\s+)?\)', line) or
        (')' in line and re.search(r'\bdef\s', recent)))


def predict_token(s, past):
    word = s.strip()
    code = past.replace('\\n', '\n').replace('\\t', '\t')
    line = code.rsplit('\n', 1)[-1]
    start = bool(re.fullmatch(r'\s*(?:\d+\s*)?', line))

    if '"""' in s or "'''" in s:
        # Distinguish opening docstrings from closing/embedded delimiters.
        indent = past.rsplit('\n', 1)[-1]
        numbered = bool(re.fullmatch(r'[+ -]*\d+\s+', indent))
        beginning = bool(re.fullmatch(r'[\s+]*r?', indent)) or numbered
        source = re.sub(r'(?m)^[ \t]*\d+\t', '', past)
        prior = source.rsplit('\n', 1)[0].rstrip() if '\n' in source else ''
        header = prior.rsplit('\n', 1)[-1]
        if beginning and python_header(prior):
            if numbered:
                return -6.0 if re.search(r'\bclass\s', header) else -8.5
            return -11.5
        module_start = not past or re.search(r'#![^\n]*\n*\s*$', past)
        module_start = module_start or header.lstrip().startswith('#')
        module_start = module_start or (numbered and int(re.search(r'\d+', indent)[0]) <= 3)
        if beginning and module_start:
            return -2.4 if not past else -4.3
        return 0.25

    if word == '->' and past.rstrip().endswith(')'):
        declaration = re.search(r'\b(def|fn|func)\s+[^{}]*\)\s*$', code[-1000:], re.S)
        if declaration:
            return {'def': -3.7, 'fn': -2.55, 'func': -0.8}[declaration[1]]
        if re.search(r'(?:\b\w+|^)\s*:\s*[&\w]', code[-300:]):
            return -2.7
    if word == 'summary' and past.endswith(('<', '</')):
        return -2.2 if '<summary>' in line else -5.4 if '///' in line else -2.0
    if word in ('brief', 'caption') and past.endswith(('\\', '@')):
        return -3.6
    if word.lower().strip('_') == 'description':
        if word.startswith('_'):
            return -2.0 if past.endswith(('pr', 'issue')) else 0.0
        if past.endswith('@'):
            return -3.7
        if word[0].isupper():
            return -0.9 if start or line.rstrip().endswith(('*', '#')) else -0.2
        if not s[0].isspace():
            quoted_key = past.endswith('"') and any(c in past[-300:] for c in '{}')
            return -2.7 if quoted_key else -0.9
        return -0.08
    if word == 'super' and start and past and s[0].isspace():
        return -3.5 if re.search(r'\bdef\s', code[-450:]) else -1.5
    if word in ('/python', '/sh', '/bash', '/env') and past.endswith('bin'):
        return (5.8 if len(past) < 15 else 1.7) if word == '/env' else 2.5
    if word == 'python' and past.endswith('/env'):
        return 2.8 if len(past) < 25 else 0.3

    # Escaped triple quotes in serialized source arrive one quote at a time.
    if '\\"' in s and re.fullmatch(r'\s*\\"[\\\"]*', s):
        before, count = code, 0
        while before.endswith('\\"'):
            before, count = before[:-2], count + 1
        indent = before.rsplit('\n', 1)[-1]
        prior = before[:-len(indent)] if indent else before
        if not indent.strip() and python_header(prior):
            return -2.7 if count or len(indent) < 7 else -4.0
        if not indent.strip() and re.search(r'#![^\n]*\n*\s*$', prior):
            return -2.7
        return -0.65 if count else 0.0
    if word and set(word) == {'·'} and len(word) >= 2 and not past.strip('·'):
        return -1.5
    if s == '\r' and not past.strip('\r'):
        return 6.6
    return 0.0


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    past = carry[1] if carry is not None and carry[0] == doc else ''
    return (doc, (past + token)[-1400:]), predict_token(token, past)

"""Sparse approximation of several lexical and formatting responses.

The largest pulse is negative on the colon in document-initial 'Title:'.
There are smaller punctuation/control-tag biases and positive responses to
Chinese education after political-training terms, and to Rust grouped imports
(especially clap examples). Ordinary text is near zero. This is a partial
approximation, not a claim that these cases explain all the component's work.
"""
import re

READS = ()

# Political study, beliefs, discipline and loyalty, in both Chinese scripts.
POLITICAL_STUDY = (
    '党史', '黨史', '思想', '忠诚', '忠誠', '信念',
    '作风', '作風', '纪律', '紀律', '宗旨', '意识', '意識',
)
PARTY_AND_CADRES = {'党', '黨', '党员', '黨員', '干部', '幹部'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, previous, recent = 0, '', ''
    else:
        _, position, previous, recent = carry
    word = token.strip()
    value = -0.0015

    if position == 0:
        if word.isdigit():
            value = 0.0
        elif word.isascii() and word.isalpha():
            value = -0.194
        elif not any(c.isalnum() for c in word):
            value = -0.165 if token.isspace() else -0.03
        else:
            value = -0.104

    if position == 1 and previous == 'Title' and token == ':':
        value = -9.329
    elif position == 0 and token == '<|endoftext|>':
        value = -2.0605
    elif token == '<think>':
        value = -0.262
    elif token in ('</think>', '<tool_response>'):
        value = -0.20
    elif token == '</tool_call>':
        value = -0.092
    elif token in ('<|im_start|>', '<|im_end|>'):
        value = -0.044
    elif word and set(word) == {'#'} and len(word) >= 2:
        if len(word) == 2:
            value = 0.404 if position == 0 else -0.204
        elif len(word) == 3:
            value = -0.834 if position == 0 else -0.063
        else:
            value = -0.15
    elif word == '**':
        value = -1.22 if position == 0 else -0.078
    elif word == '``':
        value = -0.074
    elif token == '://':
        value = -0.107
    elif token == '{':
        value = -0.946 if position == 0 else -0.057
    elif token == '}':
        value = -0.389 if position == 0 else -0.038
    elif word and set(word) == {'·'} and len(word) >= 2:
        value = 0.54
    elif word and set(word) == {':'} and len(word) >= 6:
        value = -1.214
    elif token == '::{':
        value = 0.15
        if previous.strip() == 'clap':
            value = 0.8 if re.search(r'#\s*use\s+clap$', recent) else 0.4
    elif word == '教育':
        value = 0.05
        if previous in ('学习', '學習'):
            value = 0.25
        if any(term in previous for term in POLITICAL_STUDY):
            value = 0.60
        if previous in PARTY_AND_CADRES:
            value = 1.25
        if previous in ('老师', '父母'):
            value = 0.80

    return (doc, position + 1, token, (recent + token)[-128:]), value

programs.haiku:
"""Layer 1, MLP down-projection component 6094.

What it does, in plain terms
  Positive: it fires when the text is singling out one particular part or item:
    "this one", "that part", "the best part", "the last bit", "this step";
    weaker for a bare "the part"; and on "the" in presentational phrases such as
    "here's the ...", "here comes the ...", "I got the ...", "need the ...", and on
    "where" in "here's where".
  Negative: it dips on words about having, lacking, quantity or existence:
    "has its own", "have more", "has so much", "plenty of", "lack of", "no such",
    "there are no", "any", and the Chinese/Vietnamese existence words 有 / có / nhiều.
  Almost everywhere else it is near zero, so the program predicts 0 by default.

The program is a small set of word lists plus one rule per pattern; each value is
roughly the average activation that pattern gets on sample text (eval-independent,
fit on 10k training rows). It only looks at the current word and the one before it.
"""

READS = ()

# Noun heads that stand in for a part or item of something.
# Values: (after a singling word, after "the", otherwise).
ITEM_NOUNS = {
    " part": (4.0, 2.0, 0.8),
    " parts": (3.0, 1.0, 0.6),
    " bit": (3.5, 0.8, 0.3),
    " bits": (3.0, 0.8, 0.3),
    " one": (2.7, 0.0, 0.1),
    " step": (0.9, 0.6, 0.15),
}
# Words that single out one item when they come right before the noun.
SINGLING = {" this", " This", " that", " That", " which", " best", " last", " first", " most",
            " important", " interesting", " hardest", " worst", " next", " second",
            " annoying"}

HERE_IS = {"'s", "’s"}                                # "here's", "there's"
FOUND_THE = {" got", " need", " want", " found", " had"}  # "I got the", "need the"
SEE_THE = {" get", " have", " see", " find", " saw", " seen"}

# Having / lacking / existence context.
HAVE = {" has", " have", " had", " having", " with", " without", " no", " there", " is"}
QUANTITY = {" such", " so", " more", " its", " many", " much", " exactly", " plenty",
            " other", " any", " another", " some", " still"}
ABUNDANCE_OF = {" plenty", " lack", " abundance", " absence", " wealth", " plethora", " thousands"}
HAVE_OR_BE = {" has", " have", " had", " with", " are", " is", " were", " been", " there"}
EXISTENCE_ZH_VI = {"有", "有一", "有些", "有人", "也有", "已有", "有很多", "có", "nhiều"}


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2] if same_doc else ""

    if cur in ITEM_NOUNS:
        after_single, after_the, other = ITEM_NOUNS[cur]
        if prev in SINGLING:
            return carry, after_single
        if prev == " the":
            return carry, after_the
        return carry, other
    if cur == " where" and (prev in HERE_IS or prev == " is"):
        return carry, 1.5
    if cur == " the":
        if prev in HERE_IS or prev in FOUND_THE:
            return carry, 1.5
        if prev in SEE_THE:
            return carry, 0.5
        return carry, 0.0
    if cur == " such" and prev == " no":
        return carry, -3.0
    if cur in QUANTITY and prev in HAVE:
        return carry, -0.8
    if cur == " of" and prev in ABUNDANCE_OF:
        return carry, -1.0
    if cur == " no" and prev in HAVE_OR_BE:
        return carry, -0.4
    if cur == " any" and prev in {" are", " were"}:
        return carry, -0.75
    if cur in EXISTENCE_ZH_VI:
        return carry, -0.4
    return carry, 0.0

programs.sol:
"""A local relational-phrase detector.

Quantifiers are usually quiet, but become large after connectors: 'among
other(s)', 'after/above all', 'between each/both', and 'than ever'. A connector
can carry through a short quantifier phrase ('among many other things').
Related collocations, translated relational phrases and inter- word parts
also respond. Formatting and view counters are left unmodelled.
Rounded training amplitudes approximate these local peaks, not the remaining
small, varied activations. Only four preceding tokens are kept, resetting at document boundaries.
"""
READS = ()

QUANTIFIERS = {'all', 'each', 'both', 'every', 'any', 'many', 'much',
               'anything', 'everything', 'ever', 'other', 'others', 'things'}
CONNECTORS = {'among', 'amongst', 'between', 'after', 'above', 'than', 'as',
              'of', 'over', 'through', 'with', 'about', 'beyond', 'despite'}
OTHER_FORMS = {'otros', 'otras', 'outros', 'outras', 'ander', 'andere', 'autres'}


PHRASES = {
    ('either', 'way'): 3.0, ('natural', 'language'): 2.0,
    ('civil', 'society'): 3.2, ('internal', 'format'): 2.9,
    ('relative', 'frequency'): 2.7, ('relative', 'error'): 1.7,
    ('relative', 'value'): 2.5, ('inverse', 'operation'): 0.7,
    ('subject', 'matter'): 0.8, ('après', 'avoir'): 2.2,
}


def response(token, previous):
    word = token.strip().lower()
    last = previous[-1].strip().lower() if previous else ''

    if word in QUANTIFIERS:
        connector = last
        # Only quantifier modifiers may intervene in the relational phrase.
        for old in reversed(previous[-4:]):
            old = old.strip().lower()
            if old in CONNECTORS:
                connector = old
                break
            if old not in {'other', 'many', 'each', 'his', 'their'}:
                break
        if connector in {'among', 'amongst'}:
            if word == 'other':
                return 4.4 if last == 'each' else 10.5
            if word == 'things':
                modifiers = [p.strip().lower() for p in previous[-3:]]
                return 3.0 if 'many' in modifiers else 6.5
            return {'others': 8.0, 'many': 4.8,
                    'all': 1.9}.get(word, 1.0)
        if connector == 'between':
            return {'both': 8.7, 'each': 5.4, 'all': 3.2,
                    'any': 1.15, 'every': 4.3, 'other': 1.8}.get(word, 0.2)
        if connector in {'after', 'above'}:
            if token == 'All':  # inside CamelCase compounds
                return 4.0
            return {'all': 6.3, 'each': 2.5, 'every': 3.0,
                    'much': 6.5, 'many': 4.0,
                    'everything': 4.8}.get(word, 0.0)
        if connector == 'than':
            if word == 'ever' and len(previous) > 1:
                if previous[-2].strip().lower() == 'more':
                    return 8.6
            return {'ever': 6.3, 'anything': 4.5, 'any': 2.5}.get(word, 0.0)
        if word == 'all' and last == 'of' and len(previous) > 1:
            if previous[-2].strip().lower() == 'most':
                return 3.8
        if connector == 'as' and word == 'ever':
            return 1.95
        if connector in {'of', 'over', 'through', 'with', 'about',
                         'beyond', 'despite'} and word not in {'other', 'others'}:
            return 0.5 if word != 'everything' else 0.9
        return -0.14 if word in {'other', 'others', 'much', 'ever'} else 0.0
    if word in OTHER_FORMS and last in {'entre', 'unter', 'onder'}:
        return 7.3 if last in {'unter', 'onder'} else 10.5
    if last == 'entre' and word in {'si', 'sí'}:
        return 5.7
    if last == 'между' and word == 'собой':
        return 3.3
    if word == 'name':
        return 2.15 if last == 'given' else 0.06
    if word == 'awareness':
        return {'raise': 5.5, 'raising': 5.5, 'raised': 5.5,
                'spread': 2.5, 'bring': 2.0}.get(last, 0.0)
    if (last, word) in PHRASES:
