        elif s.startswith(']]'):
            value = -2.45
        elif s.startswith('])'):
            value = -1.2 if s == '])' else -0.8
        elif s.startswith('))'):
            value = -1.7
        elif s.startswith(('{{', '}}')):
            value = -2.2
        elif s.startswith('^'):
            value = -5.0
        elif s.startswith('#'):
            value = -1.8
        elif s.startswith(('xc', 'xe')):
            value = -1.4 if s.startswith('xc') else -0.43
