    if japanese and token == '談' and previous.endswith('相'):
        value = 9.5                         # 相談: consultation
    elif japanese and token == '規' and previous.endswith('新'):
        value = 7.5                         # 新規: new registration
    elif japanese and HAN.fullmatch(token):
        value = {'相': 1.8, '共': 3.4, '新': 0.8}.get(previous.strip(), 0.0)
    elif token in ('ら', 'り', 'れ', 'ろ'):
