    elif token in ('いて', 'えて', 'んで'):
        value = -1.1                        # te-form fragments
    elif token in ('って', 'めて'):
        value = -0.4
    elif token == 'して':
        value = -0.2
    elif token == 'でも':
        value = -1.0                       # even / also
    elif token == '··':
        value = 0.56                        # doubled interpunct
    elif token == '</tool_call>':
        value = -0.2
    elif token == '</tool_response>':
        value = 0.14
