import unicodedata

READS = ()


def _is_thai(s):
    return any("THAI" in unicodedata.name(ch, "") for ch in s)


def step(carry, prefix, upstream):
    return carry, (0.08 if _is_thai(prefix.token_strings[-1]) else 0.0)

