        return 1.28
    if token.isspace():
        return -.18
    if token.startswith(' '):
        return .81
    if word.istitle():
        return .10 if len(word) == 1 else -.52
    return .07 if not token.isascii() else -.21


def assignment(tail):
    line = re.split(r'\n|\\n', tail)[-1]
    line = line.replace('\\t', '\t').replace('`', '')
    indented = bool(re.match(r'(?:[ \xa0]{2,}|\t|\s*\d+\t)', line))
    line = re.sub(r'^\s*\d+\t', '', line)
    # Mathematical notation is not a programming assignment.
    if re.search(r'\\[A-Za-z]+|\p{Script=Greek}|\p{No}|[∑∫√⇒≈]|\$\$', line):
        return 0.0
    if line.lstrip().startswith('//') and len(line.split()) > 4:
        return 0.0
    # An unmatched quote suggests the sign is inside a string, not syntax.
    if line.count('"') % 2 or line.count("'") % 2:
        return .12
    recent_code = bool(CODE_CONTEXT.search(tail))
    match = re.search(r'([\w$]+)$', line)
    word = match[1] if match else ''
    if not word:
        indexed = line.endswith((']', ')'))
        return .4 if indexed and (indented or recent_code) else 0.0
    if word.isdigit() or word.lower() in MATH_NAMES:
        return 0.0
    declared = bool(DECLARATION.match(line.lstrip()))
    variable_shape = bool(re.search(r'[_$]', word)) or bool(
        len(word) > 3 and re.search(r'[a-z][A-Z]|^[A-Z]+$', word))
    bare_name = bool(re.fullmatch(r'\s*[\w$]+', line))
    code = (indented or declared or recent_code or variable_shape or
            (len(word) >= 3 and bare_name))
    if not code:
        return .02
    if re.search(r'\w\.\w|->|::|\[', line):
        return .65
    return 1.45 if declared else 1.20


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    history = b'' if start else carry[1]
    tail = history.decode('utf-8', errors='replace')
    token = prefix.token_strings[-1]
    if start:
        value = opening(token)
    elif token == ' =':
        value = assignment(tail)
    elif token == ' :=':
        value = 1.24
    elif token.strip() in {'+=', '-=', '*=', '/=', '&=', '|=', '^=', '%='}:
        value = .23
    elif token == 'param' and tail.rstrip().endswith('@'):
        value = 1.35
    elif token == 'return' and tail.rstrip().endswith('@'):
        value = .4
    elif token == 'php' and tail.endswith('<?'):
        value = 2.0
    elif token == ' by' and tail.endswith(' Created'):
        value = 1.8
    else:
        value = 0.0
    history = (history + prefix.token_bytes[-1])[-400:]
    return (doc, history), value

"""Approximate the strong, local EA/EE spelling responses.

Selected word families such as seal, meal and appeal give negative values,
as do E-AL and E-EL joins across tokens.  Other selected E-vowel joins and
short, uncommon EA/EO fragments give positive values.  Inflection and case
adjust the magnitude; nearby 'big' strengthens deal.  Recent function-word
tokens distinguish Romance-language sea and -ear from English uses.
Unrecognized patterns get zero.  State resets at document boundaries.
"""
import re
import regex
from functools import lru_cache
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()

# Base responses for recognizable spelling families, not token IDs.
WORD_FAMILIES = {
    'seal': -6.4, 'meal': -4.6, 'deal': -3.5,
    'appeal': -2.5, 'reveal': -2.3, 'repeal': -4.1,
    'heal': -2.0, 'peel': -2.2, 'teal': -5.2,
    'zeal': -2.1, 'neal': -1.7, 'seem': -1.4, 'veal': -4.2,
}


@lru_cache(maxsize=32768)
def word_response(token):
    word = token.strip().lower()
    for root, base in WORD_FAMILIES.items():
        if not word.startswith(root):
            continue
        ending = word[len(root):]
        if ending not in ('', 's', 'ed', 'ing', 'ings', 't'):
            continue
        factor = 1.0
        if root == 'seal':
            factor = 1.15 if ending == 's' else .83 if ending else 1.0
        elif root == 'meal':
            factor = .62 if ending else 1.0
            if not token[:1].isspace():
                factor *= 1.5
        elif root == 'deal':
            factors = {'s': .71, 'ing': .66, 'ings': .57, 't': .43}
            factor = factors.get(ending, 1.)
            if token.strip().istitle():
                factor *= 1.9
        elif root == 'appeal':
            factor = .65 if ending in ('s', 'ing') else .9 if ending else 1.
            if token.strip().istitle():
                factor *= 1.4
        elif root == 'reveal':
            factor = .35 if ending == 'ed' else .65 if ending == 'ing' else 1.
        elif root == 'seem':
            factor = .36 if ending == 's' else .6 if ending == 'ed' else 1.
        elif ending in ('ed', 'ing'):
            factor = .25 if root in ('heal', 'peel') else .5
        return base * factor
    return -1.5 if word == 'deline' else 0.0


# Function words provide a small, decaying cue for Romance-language text.
ROMANCE = set("el la los las del que con por para una como pero de en "
              "do da dos das uma em não é mais mas um".split())
ENGLISH = set("the and of to with is this that was for from are "
              "it his her their have has be not".split())


@lru_cache(maxsize=32768)
def short_vowel_fragment(token):
    # Short, uncommon EA/EO pieces, rather than ordinary English words.
    return (token.islower() and len(token) >= 3
            and re.fullmatch(r'[a-z]{0,2}e(?:a[rmnsu]?|os?)', token)
            and (token == 'ear' or zipf_frequency(token, 'en') < 4.0))


def vowel_join(previous, token):
    # Transliteration is useful for related alphabetic spellings, not Han or kana.
    if regex.search(r'[^\p{Latin}\p{Cyrillic}\p{Greek}\p{Common}\p{Inherited}]',
                    previous + token):
        return 0.0
    if token[:1].isupper() and previous[-1:].islower():
        return 0.0
    p, s = anyascii(previous).lower(), anyascii(token).lower()
    if not s.isalpha() or not p.endswith('e'):
        return 0.0
    left = p[-2:-1]
    if re.fullmatch(r'al(s|ed|ing|ers?|e|a)?', s):
        base = {'s': -9., 'p': -6., 'd': -5.5,
                'v': -8., 'h': -5.}.get(left, -2.8)
        if s != 'al':
            if s in ('als', 'aling'):
                base *= .65
            elif s in ('ala', 'aler', 'alers'):
                base *= .4
            else:
                base *= .85
        return base
    if re.fullmatch(r'el(s|ing|y)?', s):
        return -1.2 if s != 'el' else -3.0
    if s in ('ada', 'ado', 'adas', 'ados'):
        return 0.0 if left == 'l' else 3.3
    if s == 'ate':
        return 4.0 if left in 'mr' else 1.5
    if s == 'ation':
        return {'m': 5.0, 'd': 2.7}.get(left, .3)
    if s in ('ating', 'ated'):
        return 3.0 if left == 'm' else .3
    if s in ('acao', 'acoes', 'acion'):
        return 0.0 if left == 'r' else 3.2
    if re.fullmatch(r'ar(?:on|am|an|ia)|an(?:ia|os)|amento', s):
        return 2.5
    if s == 'ou':
        return 4.5
    if s in ('o', 'os'):
        return .3 if left in 'hlpf' else 2.4
    if s == 'a':
        return 2.3 if len(p) >= 3 and p[-3] in 'aou' else .6
    if s == 'an':
        return 2.7 if left in 'rd' else .6
    if s == 'ar':
        return 4.5 if left == 'u' else (1.8 if left in 'rs' else .8)
    if s == 'as':
        return 2.5 if p.endswith('habe') else .1
    if s == 'ae':
        return 1.4
    if re.fullmatch(r'an(?:ia|os|e|ea)|and(?:er|ra)|ary', s):
        return 1.5
    if s in ('ia', 'io', 'ius'):
        return 1.5
    if s in ('e', 'es', 'en'):
        return .4
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, language, big = '', 0., 0
    else:
        _, previous, language, big = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    language = .97 * language + (word in ROMANCE) - (word in ENGLISH)
    big = 6 if word == 'big' else max(0, big - 1)
    value = word_response(token)
    if value and word.startswith('deal') and big:
        value *= 1.8
    if not value:
        value = vowel_join(previous, token)
        if not value and short_vowel_fragment(token):
            value = 4.0 if token == 'ear' and language > .5 else .85
        if word == 'sea' and language > .5:
            value = 2.5
    return (doc, token, language, big), float(value)

programs.haiku:
"""layers.1.mlp.down_proj:6107 as a 'coordinating conjunction' detector.

What it does: the component fires on a word that joins two parallel items,
i.e. "and", "or" and their counterparts in other languages (und, og, och, y,
et, e, ve, oder, и, или, 和, 或 ...). It is strongest when the conjunction
joins verbs or a list of actions ("to build and", "can be accessed and",
"identify, investigate, protect, and"), weaker after nouns, and near zero after
adjectives ("social and", "physical and"). Other tokens are ~0.

Why: the program is a readable rule, not a lookup table. Its overall scale
(0.5) was set by a least-squares fit to the activations on training text.

Limits: on eval it explains about 0.165 of the variance (r = 0.41), and it
switches the output about as much as zeroing the component does (kl_fraction
about 0.97). Most of the remaining spread within conjunctions depends on
context that these word-level cues do not capture.
"""

READS = ()

# English conjunctions are weaker than the same job done in other languages.
ENGLISH = {"and", "or", "nor"}
OTHER = {"og", "och", "und", "et", "e", "y", "ja", "dan", "și", "şi", "és", "ed",
         "ou", "ve", "và", "oder", "или", "и", "eller", "oraz", "atau", "και",
         "αι", "و", "ile", "sowie", "或", "和", "并", "与", "及"}
# Russian and Chinese conjunctions fire less than the Latin-script ones.
WEAK_OTHER = {"и", "или", "或", "和", "并", "与", "及"}
# Words that often precede a passive or a verb phrase ("can be", "should be").
PASSIVE_HELPERS = {"be", "been", "being", "is", "are", "was", "were", "can",
                   "will", "should", "must", "to"}
ADJECTIVE_ENDINGS = ("al", "ic", "ous", "ive", "ful", "ble", "ent", "ary", "ian",
                     "ish", "less")


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    # A comma right after a past participle starts a verb list ("designed, built,").
    if word == "," and len(prefix) > 1:
        if prefix.token_strings[-2].strip().lower().endswith("ed"):
            return None, 0.1
    if word not in ENGLISH and word not in OTHER:
        return None, 0.0

    value = 0.3 if word in ENGLISH else (0.5 if word in WEAK_OTHER else 1.0)
    if len(prefix) > 1:
        before = prefix.token_strings[-2].strip()
        lower = before.lower()
        if before == ",":
            value += 0.5                  # last item of a list: "a, b, and"
        elif before.isalpha():
            if lower.endswith("ed"):
                value += 0.8              # after a past participle: "designed and"
            elif lower.endswith("ing"):
                value += 0.5              # after a gerund: "using and"
            elif lower.endswith(ADJECTIVE_ENDINGS):
                value -= 0.4              # after an adjective: "social and"
    recent = [s.strip().lower() for s in prefix.token_strings[-4:-1]]
    if any(s in PASSIVE_HELPERS for s in recent):
        value += 0.4
    return None, 0.5 * float(value)

programs.sol:
"""A partial approximation of a word-piece spelling feature.

The main negative responses are around meng-/peng- (Indonesian nasal
prefixes), meg- (Hungarian), and joins that complete those spellings.
Short stem pieces respond more strongly. Indonesian discourse particles,
Thai /an/ syllables, and repeated middle dots have positive responses.
These are spelling rules, not a claim to recognize a word's true meaning.
"""
import re
READS = ()
# First-stem offset, then the small response on the following piece.
PREFIXES = {
    'meng': (0.70, -0.47), 'peng': (-0.69, -0.93),
    'meg': (0.00, -0.70), 'mem': (0.00, -0.35),
    'pem': (1.10, -0.23), 'men': (-0.45, 0.00),
    'pen': (-0.37, 0.00), 'meny': (-0.96, -0.23),
    'peny': (-0.57, 0.00),
}
PARTICLES = {  # Common Indonesian discourse/modal words.
    'tentu': 6.39, 'pasti': 6.13, 'nanti': 3.99,
    'namun': 3.23, 'begitu': 2.18, 'memang': 3.63,
}
FUNCTION_WORDS = frozenset(
    'yang dan untuk dengan tidak ini itu dari atau juga akan pada dalam '
    'adalah oleh karena sebagai sudah bisa lebih harus'.split())


def step(carry, prefix, upstream):
    doc, text = prefix.document_ids[-1], prefix.token_strings[-1].lower()
    if carry is None or carry[0] != doc:
        previous, word, language, age, linger = '', '', 0.0, 0, 0.0
    else:
        _, previous, word, language, age, linger = carry
    old_word, prev = word, previous.strip()
    language *= 0.96
    if text.strip() in FUNCTION_WORDS:
        language = min(1.0, language + 0.3)
    continues = bool(word and text and text[0].isalpha())
    word = re.match(r'[^\W\d_]*', word + text if continues
                    else text.lstrip()).group()
    value, next_linger = -0.001, 0.0
    if continues:
        vowel = text[0] in 'aeiouáéíóöőúüű'
        stop = text[0] in 'bp'
        value += linger
        if prev in PREFIXES:
            offset, next_linger = PREFIXES[prev]
            value += offset
            if prev in ('meng', 'peng'):
                value -= (2.03 / max(1, len(text)) + 2.23 * vowel
                          + 0.26 * language + 1.89 * previous.startswith(' '))
            elif prev == 'meg':
                value -= 3.07 / max(1, len(text)) + 1.24 * stop
            else:
                value += 0.65 * vowel - 0.68 * stop - 1.68 * language
        if prev in ('men', 'pen') and text.startswith('g') and len(text) > 1:
            value -= 4.34 + 3.34 * language
        if prev in ('m', 'p') and text.startswith('eng') and len(text) > 3:
            value -= 1.02
        if prev in ('m', 'me') and text.startswith('g') and len(text) > 1:
            value -= 0.96
        if prev in ('ng', 'eng') and old_word.endswith(('meng', 'peng')):
            value -= 0.51
        for particle, strength in PARTICLES.items():
            forms = (particle, particle + 'nya', particle + 'lah', particle + 'kah')
            if len(word) >= len(particle) and any(w.startswith(word) for w in forms):
                value += strength
    else:
        value += {'mem': 0.32, 'pem': 0.40, 'peng': -0.72}.get(word, 0.0)
        if word in ('ini', 'itu', 'pun'):
            value += 0.87 * language
        if word == 'pun' and language > 0.05:
            value += 3.38
    if word == 'past':
        value += 2.51 * language
    if 'ัน' in text:
        value += 0.29 + (2.95 if previous == 'ม' else
                         0.41 if previous.endswith(('น', 'ล')) else 0.0)
    if text == previous == '··':
        value += 0.67
    if age == 0:
        if text in ('the', 'a', 'an', 'i', 'you', 'we', 'they'):
            value -= 0.29
        if text in ('what', 'how', 'when', 'where', 'why'):
            value -= 0.51
    tail = re.search(r'[^\W\d_]+$', text)
    word = word if text.isalpha() and continues else (tail.group() if tail else '')
    return (doc, text, word[-40:], language, age + 1, next_linger), float(value)

programs.haiku:
"""layers.1.mlp.down_proj:6109 - a "name / identifier word" detector.

What it does: predicts this component's activation from the current token alone, with
no context. The component writes most strongly when the token is the word "name" (any
case, or the end of a compound such as `_name`, `fileName`, `.getName`). It is moderate
on words for identifiers, paths, locations and data types (id, path, dir, url, file,
string, list, array, json, date, index, type, title, address, number, key, ...), on
file extensions after a dot (.py, .js, .rs, .go, .json, .yaml, ...) and on common code
members after a dot (.length, .split, .get, .push, ...). Everything else is about 0.
Each class gets one fixed value, so the program is a small word-class lookup.
"""

READS = ()

# The word "name" and its compounds: the strongest class.
NAME_WORDS = {"name", "names"}

# Words for identifiers, paths, places and data types: moderate.
ID_WORDS = {
    "id", "ids", "path", "paths", "dir", "directory", "url", "uri", "file", "string", "str",
    "array", "list", "json", "date", "index", "type", "title", "street", "avenue",
    "dict", "hash", "uuid", "tuple", "coordinate", "coordinates", "address", "addr",
    "username", "email", "location",
}

# Data-ish nouns that are only sometimes identifiers: weak.
WEAK_WORDS = {
    "map", "key", "object", "text", "label", "code", "number", "vector", "matrix",
    "table", "value", "data", "field", "column",
}

# File extensions and code members, written after a dot.
EXTENSIONS = {
    "py", "js", "ts", "rs", "go", "java", "json", "yaml", "yml", "xml", "txt", "md", "csv",
    "org", "mod", "cpp", "sh", "php", "jar", "properties", "edu", "gov", "net", "png",
}
MEMBERS = {
    "length", "len", "size", "split", "substring", "tostring", "charat", "get", "put",
    "getname", "append", "push", "add", "replace", "trim", "strip", "items", "keys",
    "getstring", "gettext",
}


def step(carry, prefix, upstream):
    """The activation at the current token: a fixed value for its word class."""
    token = prefix.token_strings[prefix.position]
    word = token.strip().lower().strip("._-([\"'")
    dotted = token.startswith(".")
    if word.endswith("name") or word in NAME_WORDS:
        value = 1.6
    elif word in ID_WORDS:
        value = 1.0
    elif word in WEAK_WORDS:
        value = 0.3
    elif dotted and word in EXTENSIONS:
        value = 0.9
    elif dotted and word in MEMBERS:
        value = 0.8
    else:
        value = 0.0
    return carry, float(value)

programs.sol:
"""A document-initial, token-shape-dependent pulse, otherwise nearly zero.

The pulse persists while the document consists of copies of its first token.
Its size is approximated by formatting, capitalization, English frequency,
and a few recognizable source-code/proof introducers. It is not a general
semantic classifier: individual initial-token amplitudes remain approximate.
An end-of-message marker gets a small positive value away from the start.
Small, token-specific background fluctuations are otherwise omitted.
"""
from wordfreq import zipf_frequency

READS = ()


def initial_value(s):
    w = s.strip()
    if s == '\r':
        return 11.3
    if s.isspace():
        if '\t' in s and s.count(' ') >= 3:
            return 2.2
        return -0.6 if '\t' not in s else 0.0
    if w and set(w) == {'·'} and len(w) > 1:
        return -3.16
    if s == 'using':                  # C# using directive
        return 2.87
    if s == 'theorem':                # formal proof declaration
        return 2.42
    if w.lower() in {'str', 'char', 'string'}:
        # Character/string type names; smaller pulse when space-prefixed.
        value = {'str': 1.66, 'char': 3.56, 'string': 6.82}[w.lower()]
        return value * (0.4 if s.startswith(' ') else
                        0.3 if w[0].isupper() else 1.0)
    if '\n' in s and not any(c.isalnum() for c in s):
        if s.lstrip().startswith('}'):
            return 2.8
        if '*' in s or '//' in s:
            return 1.6
        return 0.4
    if s.startswith('.') and s[1:].isalpha():
        return 1.1                  # member access / dotted suffix
    if s.startswith('#'):
        return -1.3                 # directives and headings
    if s in {';', '{'}:
        return -5.5 if s == ';' else -7.65
    if w and w[0] in '([{':
        return -0.55
    if len(w) == 1 and w.isascii() and w.isalpha():
        return -0.35 if s.startswith(' ') else -0.85
    if w.istitle():
        frequent = zipf_frequency(w.lower(), 'en') >= 4.0
        if s.startswith(' '):
            return -0.15 if frequent else 0.4
        return -0.7 if frequent else -0.2
    return -0.05


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_bytes[-1]
    if carry is None or carry[0] != doc:
        value = initial_value(prefix.token_strings[-1])
        return (doc, token, value), value
    _, first, value = carry
    if token != first:
        value = 0.0
        first = None
    output = 0.12 if prefix.token_strings[-1] == '<|im_end|>' else value
    return (doc, first, value), output

"""Approximate a mostly negative time-relation cue.

Mid-sentence 'since' is strongest, amplified by recent perfect-tense,
persistence, duration, or superlative words.  Punctuation, connectives,
and mathematical notation weaken it.  Event/return cues make 'in'
date-like, including the next standalone space.  Other temporal words
and translations have fixed strengths; split translations are rejoined.
Case and token spacing also affect the estimates.  Only a rolling text
window is retained, reset at document boundaries.  Incidental activity
on unrelated word fragments is not modelled.
"""
import re

READS = ()
# Date-introducing life, historical-event, and reporting cues.
LIFE = set('born founded established disestablished'.split())
HISTORY = set('died built launched back'.split())
EVENT = set('published completed formed released added developed created '
            'issued opened began elected appointed introduced filed '
            'incorporated constructed started signed entered announced '
            'retired joined'.split())
RECORD = set('written mentioned defined described proposed said raised'.split())
DISPLAY = set('shown illustrated listed given figure table equation'.split())
CONNECTIVES = set('and but that because so however then as or'.split())
TIME_WORDS = re.compile(
    r'\b(first|last|best|worst|most|least|lowest|highest|time|times|'
    r'year|years|while|season|century)\b')
PERSISTENCE = re.compile(r'\b(has|have|had|been|ever|never|haven.t|hasn.t|hadn.t)\b')
MATH = re.compile(
    r'[=≠π∑∞≤≥⇒×±²³√]|\\(?:frac|sqrt|sum)|'
    r'\b(equation|integer|compute|inequality|congruent|congruence|triangle|'
    r'coordinate|polynomial|quadratic|fraction|divisible|modulo|probability|'
    r'coefficient|derivative|integral|matrix|logarithm|numerator|denominator|sqrt)\b')
WORD = re.compile(r'[A-Za-z]+')
PUNCT = re.compile(r'[,.;:?!)]\s*$')
# Temporal words and translations of since, during, or after.
RELATIONS = {
    'during': -.84, 'prior': -.95, 'pre': -.65, 'post': -1.3,
    'seit': -7.0, 'depuis': -6.0, 'siden': -5.0,
    'sedan': -3.3, 'desde': -2.8, 'منذ': -7.5,
    'durante': -.8, 'pendant': -1.05, 'während': -1.15,
    'nach': -.55, 'sejak': -8.5,
}

ENDINGS = {w[i:] for w in RELATIONS for i in range(1, len(w))}


def event_in(previous):
    if previous in LIFE:
        return -2.9
    if previous in HISTORY:
        return -2.0
    if previous in EVENT:
        return -1.0
    if previous in RECORD:
        return -.5
    return .04


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    if word in ENDINGS and text[-1:].isalpha():
        joined = re.search(r'[^\W\d_]+$', text + token)
        if joined and joined[0].lower() in RELATIONS:
            word = joined[0].lower()
    value = 0.0
