"""Layer 1 MLP down_proj component 6112.

A "time-reference opener" detector. The component goes strongly negative on the
word that opens a time reference when the model expects a date, year or period
to come next:

- "since" meaning "from then until now" ("has been ... since 2010", "a year
  since", "ever since"), and its translations (depuis, seit, desde, منذ, ...).
  "Since" meaning "because" (after "But", "So", "Then", or in reasoning text) stays near zero.
- "in" after a verb of founding, birth or publication ("born in", "built in",
  "established in") and the space token before a year that follows it.
- "during", "post", "following", "after", "pre" as time markers ("the following"
  is not one).

Elsewhere it is near zero. Strength is a judgement of how strongly a date comes next.
"""

READS = ()

PUNCT = set(",.;:()[]{}?!\"'")
DATE_VERBS = {"born", "established", "founded", "formed", "built", "published",
              "released", "died", "incorporated", "created", "produced", "written",
              "started", "starting", "opened", "completed", "launched", "introduced",
              "debut", "death"}
PERFECT_OR_SPAN = {"been", "have", "has", "had", "ever", "year", "years", "time",
                   "months", "month", "days", "day", "week", "weeks", "ago", "million",
                   "lived", "remained"}
DETERMINERS = {"the", "The", "THE", "this", "This", "a"}
CONJUNCTIONS = {"But", "but", "So", "so", "Then", "then", "Wait", "and", "However",
                "Hmm", "Thus", "Note", "Because", "because", "Alternatively"}
OTHER_SINCE = {"depuis", "Depuis", "seit", "Seit", "sedan", "Sedan", "siden", "Siden",
               "desde", "Desde", "منذ", "since", "Since"}


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    raw = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    back2 = prefix.token_strings[-3].strip() if len(prefix.token_strings) > 2 else ""
    prev = raw.strip()
    word = cur.strip()
    if word.lower() == "since" or word in OTHER_SINCE:
        if prev in CONJUNCTIONS:
            return None, -0.5
        if word not in ("since", "Since"):
            return None, -5.0
        if raw.endswith("\n") or prev == "":
            return None, -3.0
        if prev[-1:] in PUNCT:
            return None, -1.0
        recent = {s.strip() for s in prefix.token_strings[-4:-1]}
        return None, -9.0 if recent & PERFECT_OR_SPAN else -5.5
    if word in ("during", "During"):
        return None, -1.0
    if word in ("following", "Following"):
        return None, 0.0 if prev in DETERMINERS else -2.0
    if word in ("post", "Post"):
        return None, -1.5
    if word in ("after", "After"):
        return None, -0.5
    if word in ("pre", "Pre", "prior"):
        return None, -0.5
    if cur == " " and prev in ("in", "In"):
        return None, -2.8 if back2 in DATE_VERBS else -1.0
    if word == "in" and prev in DATE_VERBS:
        return None, -1.5
    return None, 0.0

