CODE_WORDS = set('def class from import package function var const let return '
                 'if else elif with for while print'.split())
CODE_MARKERS = {';', '//', "'''", '"""', '```'}
ARTICLES = {'A', 'An', 'The'}
ORDINAL = re.compile(r'\b\d{1,2}(?:st|nd|rd|th)$', re.I)
ORDINAL_OF = re.compile(r'\b\d{1,2}(?:st|nd|rd|th) of$', re.I)


