    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    if first:
        carry = (doc, 'start', '')
    _, opening, tail = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    spaces = len(token) >= 3 and not token.strip(' ')
    value = 0.0

    if not first:
        if word.lower() in WEEKDAYS:
            value = 0.08
        elif word == '"':
            value = 0.06 if token == word else 0.01
        elif word == "'":
            value = 0.035 if token == word else 0.01
        elif word and '"' in word and all(c in '\\",:;' for c in word):
            value = 0.04
        elif word in {'<', '</'}:
            value = 0.04
        elif spaces:
            value = -0.02
    else:
        if spaces:
            value = -0.55
        elif word in CODE_MARKERS:
            value = -0.95
        elif word in CODE_WORDS:
            value = -0.45
        elif word in ARTICLES:
            value = -0.25

