    if token == r'\t' and opening in {'start', 'tabs'}:
        value, opening = 1.55, 'tabs'
    elif len(token) >= 2 and not token.strip('·') and opening in {'start', 'dots'}:
        value, opening = -0.87, 'dots'
    else:
        opening = None
