    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, position = '', 0
    else:
        _, previous, position = carry
    token = prefix.token_strings[-1]
    value = 0.0
    horizontal = bool(previous) and previous.strip(' \t') == ''
    if token == ' ' and horizontal and previous.endswith(' '):
        length = len(previous)
        value = 1.62 + 0.81 / (1 + position / 20)
        if length == 1:
            value -= 0.45
        elif length == 4:
            value += 0.21
        elif length >= 5:
            value -= 0.13
