            value = -4.8
        elif re.fullmatch(r'provid(?:e|es|ed|ing)', previous):
            value = -4.3
        elif re.fullmatch(
            r'requir(?:e|es|ed|ing)|'
            r'(?:order|request|demand|ask)(?:s|ed|ing)?', previous
        ):
            value = -2.9
        elif previous == 'and':
            value = -1.9
        elif previous == 'but':
            value = -1.2
        elif previous in {'held', 'holding', 'recommend', 'recommended', 'praying'}:
            value = -1.5
        elif previous in {'hoping', 'agreed', 'now', 'normally', 'added'}:
            value = -0.8
        elif previous in {',', ';', ':', 'so', 'as'}:
            value = -0.2
        elif previous == 'such':
            value = 0.19

    elif word == 'otherwise':
        value = -4.5 if previous in {'or', 'as'} else -1.7
        if previous in {',', ';', ':'}:
            value = -0.85
    elif re.search(r'\ballowances?$', text, re.I):
        value = -3.5
    elif re.search(r'\bprovisions?$', text, re.I):
        value = -3.0
        if not token[:1].isspace() and re.match(r'vision', word):
            value = -4.3

    return (doc, text), value

programs.haiku:
"""Layer-1 MLP component 6121: a negative detector for the word that introduces what is
allowed, provided, arranged or required.

It is negative, and never meaningfully positive, on the function word after such a word:
  * " for" after a verb of allowing, providing or arranging ("allow for", "provide for",
    "arranging for", "provided for"): strongly negative, about -5;
  * " for" after a verb of fighting, advocating, asking, paying or aiming ("fought for",
    "advocated for", "asked for", "paying for"): about -1.5;
  * " for" and " that" after "and", "but" or "or" ("and for", "and that"): about -1.5 and -1.7;
  * " that" after a verb of requiring, holding or agreeing ("requires that", "held that"):
    about -2;
  * " otherwise" ("unless otherwise", "or otherwise"): about -1.5;
  * the nouns " provision", " provisions", " allowance": about -2.5, and "vision" split off
    from "pro" ("pro" + "vision" = "provision"): about -3.5.
Everywhere else it predicts 0. It reads only the current token and the one before it.
"""

READS = ()

STRONG_FOR = {"allow", "allows", "allowed", "allowing", "provide", "provides", "provided",
              "providing", "arrange", "arranges", "arranged", "arranging"}
MID_FOR = {"fight", "fights", "fought", "fighting", "advocate", "advocates", "advocated",
           "advocating", "ask", "asks", "asked", "asking", "pay", "pays", "paid", "paying",
           "push", "pushed", "pushing", "aim", "aimed", "aiming", "save", "saved", "saving",
           "equipped", "made", "make", "makes", "making", "except"}
CONJUNCTIONS = {"and", "but", "or", "nor", "yet"}
REQUIRE_THAT = {"requires", "required", "require", "requiring", "held", "agreed", "request"}
PROVISION_NOUNS = {"provision", "provisions", "allowance"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    same_doc = len(prefix) > 1 and prefix.document_ids[-1] == prefix.document_ids[-2]
    prev = prefix.token_strings[-2].strip().lower() if same_doc else ""
    value = 0.0
    if word == "for":
        if prev in STRONG_FOR:
            value = -5.0
        elif prev in MID_FOR:
            value = -1.5
        elif prev in CONJUNCTIONS:
            value = -1.5
    elif word == "that":
        if prev in CONJUNCTIONS:
            value = -1.7
        elif prev in REQUIRE_THAT:
            value = -2.0
    elif word == "otherwise":
        value = -1.5
    elif word in PROVISION_NOUNS:
        value = -2.5
    elif word == "vision" and prev == "pro":
        value = -3.5
    return carry, float(value)

programs.sol:
"""Summarize prominent layout responses without a per-token lookup.

Short runs of spaces inside text are negative, particularly after numbers.
A new indentation width after a newline is briefly positive; familiar
indentation is mostly quiet. Escaped backslashes are positive in code but
negative as LaTeX row separators. NUL bytes after ASCII letters are positive,
unlike those after whitespace. The colon of initial Title: is strongly positive.
Ordinary words are left at zero rather than memorizing their lexical responses.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        line, recent, position, widths, indents, previous = '', '', 0, {}, 0, ''
    else:
        _, line, recent, position, widths, indents, previous = carry
    token = prefix.token_strings[-1]
    value = 0.0
    n = len(token)
    if n > 1 and token == ' ' * n:
        new_width = n not in widths
        widths[n] = True
        if not line.strip():
            if previous.endswith('\n'):
                if new_width:
                    value = 0.4 if n <= 4 else (0.3 if indents == 0 else 0.0)
                else:
                    value = 0.02 if n <= 4 else -0.03
            else:
                value = -0.15 if n <= 5 else -0.02
            indents += 1
        elif line.strip() in ('//', '///', '#', '*'):
            value = -0.05
        elif n <= 6:
            value = -0.6 if n == 2 and line[-1:].isdigit() else -0.48
        elif len(line) <= 14:
            value = 0.1 if n >= 15 else -0.08
        else:
            value = -0.36 if n <= 10 else -0.23
    elif token == ' ' and not line.strip():
        value = 0.06
    if '\\\\' in token:
        # TeX commands and alignment columns, not escaped code newlines.
        latex = any(x in recent for x in (
            '\\frac', '\\left', '\\right', '\\begin', '\\hfill',
            '\\text{', '\\sqrt', '\\mathbf', '\\tilde', '\\overline'))
        latex = latex or (recent.count('&') >= 2 and '&&' not in recent)
        if '\n' in token:
            value = -0.95
        elif latex:
            value = -1.5
        else:
            value = 1.3 if '\\\\\\\\' in token else 0.8
    elif '\\"' in token and recent.endswith('\\\\'):
        value = 0.7
    elif token.strip() == '@@' and '@@' in line:
        value = 0.42
    elif token == ':' and position == 1 and line == 'Title':
        value = 11.27
    elif token == '\x00':
        if previous.isspace():
            value = -0.02
        elif previous.isascii() and previous.isalpha():
            value = 1.2
        else:
            value = 0.6
    line = (line + token).replace('\\n', '\n').split('\n')[-1][-200:]
    recent = (recent + token)[-500:]
    return (doc, line, recent, position + 1, widths, indents, token), value

"""A document-onset response, approximated by grammatical and punctuation classes.

Only the onset of each document gets a sizeable prediction. At that
position, prepositions, possessives and copulas tend positive; code-opening
keywords, negation, headings and question openings tend negative. Later tokens
get the small observed background mean (an initial run of identical tokens
keeps its onset prediction). This deliberately leaves unexplained
the component's substantial idiosyncratic variation between individual words.
Unclassified onset tokens use length, spacing, ASCII and capitalization only.
"""
import math

READS = ()

PREPOSITIONS = frozenset('in on at by of for from with as over under within'.split())
POSSESSIVES = frozenset('my your his her its our their'.split())
COPULAS = frozenset('am is are was were be'.split())
CODE_OPENERS = frozenset('import from using def public private static void'.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    if carry is not None and carry[0] == doc:
        _, first_token, onset, repeated = carry
        repeated = repeated and token == first_token
        state = (doc, first_token, onset, repeated)
        return state, onset if repeated else 0.0023
    s = prefix.token_strings[-1]
    word = s.strip()
    lower = word.lower()
    spaced = s.startswith(' ')
    # A coarse onset background: long and space-prefixed pieces tend lower.
    value = (
        -0.02 - 0.64 * math.log1p(len(word)) - 0.94 * spaced
        + 1.24 * word.isascii() + 0.27 * word.istitle()
    )
    if s.startswith('<|'):
        value = -0.34
    elif not word:
        value = 2.5 if '\n' in s or '\t' in s else 0.0
    elif word.startswith('#'):
        value = -4.2
    elif word == '.':
        value = -0.4 if '\n' in s else -2.4
    elif word == ',':
        value = 1.5
    elif word[0] in '\"\'“‘':
        value = -2.0
    elif word.startswith('•'):
        value = -3.5
    elif lower in CODE_OPENERS and not spaced and word == lower:
        value = -7.2
    elif lower == 'using':
        value = -6.0
    elif lower == 'to':
        value = -11.3 if word == 'To' and not spaced else -2.0
    elif lower in PREPOSITIONS:
        value = 4.7 if lower == 'in' else 2.1
    elif lower in POSSESSIVES:
        value = 2.3 if spaced else 4.5
    elif word == 'I':
        value = 1.4 if spaced else 5.3
    elif lower == 'you':
        value = 0.5 if spaced else 2.7
    elif lower in COPULAS:
        value = 1.5 if spaced else 3.0
    elif lower in ('a', 'an'):
        value = -0.65 if spaced else 2.4
    elif lower == 'the':
        value = 0.55
    elif lower in ('this', 'that'):
        value = -1.8
    elif lower in ('not', 'cannot', 'never'):
        value = -3.0
    elif lower in ('and', 'or', 'but'):
        value = -0.4 if spaced else 2.0
    elif lower == 'if':
        value = 2.7 if spaced else 5.0
    elif word in ('What', 'How', 'Who', 'Question') and not spaced:
        value = -5.7
    return (doc, token, value, True), value

programs.haiku:
"""layers.1.mlp.down_proj:6123: a document-opener detector.

The component is silent inside a document. It only speaks on a document's first token
(the token after `<|endoftext|>`, or the first token of a row). There its value is set by
which token opens the document, and it is a fixed function of that token alone: the first
position attends only to itself, so the same token always gives the same value. The program
sorts opening tokens by what kind of text they start:

  * negative: code and markup openers (`#`, `#include`, `//`, `<?`, `import`, `def`, `using`),
    technical single letters (`C`, `c`, `D`, `M`, `H`), instruction and prompt openers
    (`To`, `What`, `How`, `Can`, `Please`, `Question`, `Translate`), verb and noun endings
    (-ing, -ed, -tion, -ment, -able), non-Latin scripts (Cyrillic, Thai, Arabic, Korean,
    kana), and half of a multi-byte character;
  * positive: prose openers: narrative and news starts (`In`, `I`, `My`, `When`, `Recently`,
    `Today`), names (`Dave`), function words after a space (` of`, ` for`, ` were`), symbols
    after a space (` $`, ` &`, ` |`), lone lowercase or capital letters, commas, newlines and
    tabs, and Chinese news phrases (`近日`).

Every other token, and every position inside a document, predicts 0. Each group's value is
the mean activation of its tokens over ~90k training document starts. The sign and rough
size are captured, but not the exact value of each token, so the fit is partial.
"""

import re

READS = ()

# Matched on the exact token string (no stripping), so "{\n" is not "{".
SYMBOL_OPENERS = {
    "#", "##", "###", "//", "/*", "<?", "<", "`", '"', "'", "“", "{", "【", "•", "**", "()",
    "<|endoftext|>",
}
TECH_LETTERS = {"C", "c", "D", "M", "H"}
CODE_WORDS = {"import", "from", "def", "using", "print", "include", "#include", "public", "null",
              "return", "class", "function", "math", ".util"}
PROMPT_WORDS = {"to", "what", "how", "can", "cannot", "not", "please", "question", "translate",
                "test", "text", "comment", "more", "new", "different", "this", "which"}
PROSE_WORDS = {"in", "my", "our", "here", "when", "if", "as", "at", "after", "over", "today",
               "recently", "last", "mid", "is", "for", "you", "dave", "james", "william", "david",
               "john", "george", "bob", "frank", "brad", "kim", "hi", "person"}
SPACED_FUNCTION_WORDS = {" of", " for", " on", " at", " by", " is", " are", " was", " were",
                         " with", " about"}
CHINESE_NEWS = {"近日", "最近", "中新网", "您好", "各位", "获悉", "据悉", "记者"}
NON_LATIN = re.compile(r"[Ѐ-ӿ฀-๿؀-ۿ가-힯぀-ヿ]")
WORD_ENDING = re.compile(r"\s?[A-Za-z]+(ing|ed|tion|ment|able)")
SPACED_SYMBOL = re.compile(r" [^\w\s\"'“”`]+")


def opener_value(token: str) -> float:
    """The activation of a document-opening token, from its concept group."""
    word = token.strip()
    low = word.lower()
    if "�" in token:
        return -3.0
    if NON_LATIN.search(token):
        return -2.0
    if word in CHINESE_NEWS:
        return 12.0
    if token in SYMBOL_OPENERS or token in TECH_LETTERS:
        return -4.0
    if token in CODE_WORDS:
        return -3.0
    if low in PROMPT_WORDS:
        return -2.0
    if WORD_ENDING.fullmatch(token):
        return -2.0
    if token == ".":
        return -1.8
    if token == ",":
        return 1.5
    if token.strip() == "":
        return 3.0 if ("\n" in token or "\t" in token) else 0.0
    if token in SPACED_FUNCTION_WORDS or SPACED_SYMBOL.fullmatch(token):
        return 2.5
    if low in PROSE_WORDS:
        return 3.0
    if re.fullmatch(r"[a-z]", token) or re.fullmatch(r"[A-Z]", token):
        return 2.5
    return 0.0


def step(carry, prefix, upstream):
    """Called once per token. Nonzero only at the first token of a document."""
    t = prefix.position
    starts_document = t == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if not starts_document:
        return None, 0.0
    return None, opener_value(prefix.token_strings[-1])

"""Layer-1 MLP down_proj component 6124 (v4).

What it does, in plain terms:
- It is a sparse "division operator" detector. It fires on the token that
  introduces the denominator of a division or fraction:
    * TeX infix fraction/binomial macros: `{a \\over b}`, `{n \\choose k}`.
      Strongest when the backslash is a bare control-sequence backslash;
      weaker when it sits right after an opening maths delimiter ($ or \\().
    * the words "divided by" in arithmetic ("25 divided by 14"); weak in prose.
- It fires on the `command` of `\\newcommand` (and a little on `new`).
- It is strongly negative on the forum signature "[#permalink".
- It is slightly negative on the first token of every document.
- It is 0 elsewhere (the bulk of its small variance is not captured here).
"""
READS = ()

MATH_END = ("x", "n", "k", ")", "]", "}")  # tokens that can end a dividend


def ends_bs(s):
    return s.endswith("\\")


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if len(prefix) == 1 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, -0.22  # first token of a document
    prev = prefix.token_strings[-2]
    if tok in ("over", "choose") and ends_bs(prev):
        # a bare backslash (or "}\\") gives the full response; "$\\" or "(\\" less
        value = 5.3 if prev in ("\\", " \\", "}\\", " }\\") else 2.3
    elif tok == "command" and prev == "new":
        value = 4.2  # \newcommand
    elif tok == "new" and ends_bs(prev):
        value = 1.0
    elif tok == " by" and prev == " divided":
        before = prefix.token_strings[-3] if len(prefix) > 2 else ""
        numeric = before.strip().isdigit() or before.strip() in MATH_END
        value = 1.6 if numeric else 0.3  # "12 divided by 3" vs prose
    elif tok == "permalink":
        value = -5.5  # forum signature artifact "[#permalink"
    elif tok == "⎯" and prev == "⎯":
        value = -2.4  # runs of box-drawing bar
    elif tok == "··" and prev == "··":
        value = -0.6  # runs of middle dots
    else:
        value = 0.0
    return carry, value

programs.sol:
"""Detect a document's initial run of identical tokens.

The pulse continues while the prefix contains only repetitions of its first
token, then switches off. Its height is estimated from that token's shape:
Latin letters and indentation generally exceed digits, punctuation and non-Latin
writing. These broad classes leave individual words' variation unexplained.
"""
import math
import regex

READS = ()


def start_height(text):
    if text == '<|im_start|>':
        return 3.6
    if text == '<|im_end|>':
        return 2.1
    if text == '<|endoftext|>':
        return 9.1

    word = text.strip()
    if not word:
        if '\n' in text or '\r' in text:
            return 4.7
        if '\t' in text:
            return 8.0
        return min(10.0, 5.8 + 1.4 * math.log2(max(1, len(text))))

    if not word.isascii():
        return 6.5 if regex.search(r'\p{Script=Cyrillic}', word) else 5.2
    if word.isdigit():
        return 5.8
    if word.isalpha():
        if text == word:
            return 8.8 if len(word) == 1 else 7.6
        if len(word) == 1:
            return 6.3 if word.isupper() else 7.5
        return 6.5 if len(word) <= 3 else 7.3
    if any(ch.isalpha() for ch in word):
        return 8.1
    if '\n' in text:
        return 4.5
    return 7.2 if '#' in word else 5.8


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    if carry is None or doc != carry[0]:
        height = start_height(prefix.token_strings[-1])
        carry = (doc, token, height)
    elif token != carry[1]:
        carry = (doc, None, 0.0)
    return carry, carry[2]

programs.haiku:
"""Layer 1 MLP down-projection, component 6126: a mostly silent, token-specific component.

Plain-terms summary. Its activation is usually within about +/-0.1 of zero. It is large
on a few kinds of token, and this program predicts those:

1. Angle and triangle notation (maths): the word "angle" (about -0.5, and about -0.8 when
   the text nearby is maths), the angle sign ∠ (about -4.6) and the triangle sign △.
2. Other maths/LaTeX words (\\vec, \\operatorname, \\color, \\phantom, \\pu, ÷, ⋅): mildly
   negative, about -0.5.
3. Chinese/Japanese reading and browsing words (阅读, 閱讀, 浏览, 瀏覽, 読, 订阅, 阅):
   positive, about +1 to +2.
4. The repeated middle-dot token "··" (a dot leader): about -1.25. It was seen only in a
   few documents in the sample, so it is the least certain entry.
5. The first token of a document (or of a packed row), which has no earlier context:
   digits about +0.2; spaces, newlines and function words about -0.2; other words +0.1.

Everything else predicts 0. Most of the variance is diffuse small noise that no short
rule captures, so the variance explained is small.
"""

READS = ()

ANGLE_SIGNS = {"∠": -4.6, "△": -0.9}
ANGLE_WORDS = {"angle", "(angle", "Angle"}
MATH_WORDS = {"vec", "operator", "color", "phant", "pu", "÷", "⋅"}
READING = {"阅读", "閱讀", "浏览", "瀏覽", "読", "订阅", "阅"}
FUNCTION_WORDS = {"the", "of", "to", "in", "and", "is", "a", "for", "with", "on", "it", "that", "This", "The", "I", "We"}
MATH_MARKERS = ("$", "\\", "°", "triangle", "degree")


def doc_start_value(word):
    w = word.strip()
    if w.isdigit():
        return 0.2
    if w == "" or w in FUNCTION_WORDS:
        return -0.2
    return 0.1


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    word = tok.strip()
    t = prefix.position
    docs = prefix.document_ids
    if t == 0 or docs[-1] != docs[-2]:
        return None, doc_start_value(tok)
    if tok == "··":
        return None, -1.25
    if word in ANGLE_SIGNS:
        return None, ANGLE_SIGNS[word]
    if word in ANGLE_WORDS:
        nearby = prefix.token_strings[-30:]
        maths = any(m in s for s in nearby for m in MATH_MARKERS)
        return None, -0.8 if maths else -0.5
    if word in MATH_WORDS:
        return None, -0.5
    if word in READING:
        return None, 1.5
    return None, 0.0

programs.sol:
"""Detect introductions to reported facts and explanations.

`that` is strong after evidence/reporting verbs, but weak as a relative or
pointing word. Embedded `how` is stronger still; direct questions are weak.
A few related manner, reason, and completion words have smaller responses.
At document starts, words and numbers receive small positive baselines.
Unlisted tokens otherwise get zero. A rolling text context resets with each
document; no later tokens are consulted.
"""
import re
import wordnet

READS = ()

EVIDENCE = set('show find discover reveal demonstrate illustrate highlight '
               'observe'.split())
INFERENCE = set('suggest indicate imply report determine explain describe '
                'examine investigate emphasize hypothesize propose identify '
                'outline clarify '
                'theorize reason recommend envision'.split())
THOUGHT_SPEECH = set('say tell state note mention know think believe assume '
                    'suppose understand expect hope agree ensure remember '
                    'realize notice verify check learn mean announce argue '
                    'claim assert acknowledge recognize inform remind warn '
                    'assure see consider predict prove confirm establish '
                    'conclude teach recall '
                    'decide declare testify hold rule allege contend realise'.split())
FACT_NOUNS = set('fact evidence conclusion hypothesis belief thought idea '
                'possibility likelihood understanding impression point'.split())
CERTAINTY = set('sure certain clear obvious aware convinced confident '
                'important apparent likely unlikely'.split())
PREPOSITIONS = set('in of for to at with as on from by into after before '
                   'than'.split())
MODALS = set('to can could should must will would may might'.split())
ACTION_OR_WANT = set('do have get make take give put use like want need'.split())


def roots(word):
    return set(wordnet.base_forms(word)) | {word}


def predict(token, context, first=False):
    word = token.strip().lower()
    if (context and context[-1].isalnum()
            and token[:1].isascii() and token[:1].isalnum()):
        return 0.0
    if first and word not in {'that', 'how', 'why'}:
        if token.strip().isdigit():
            return 0.53
        if token.strip().isalpha():
            return 0.24
        return 0.0
    if word not in {'that', 'how', 'why', 'where', 'whether', 'way', 'ways',
                    'already', 'means', 'meaning', 'что', 'أن', 'because'}:
        return 0.0
    words = re.findall(r"[\w']+|[^\w\s]", context.lower())
    prev = words[-1] if words else ''
    before = words[-2] if len(words) > 1 else ''
    base = roots(prev)
    evidence = bool(base & EVIDENCE)
    inference = bool(base & INFERENCE)
    categories = wordnet.categories(prev)
    lexical_verb = bool(categories & {'verb.communication',
                                      'verb.cognition', 'verb.perception'})
    if (before in {'a', 'an', 'the', 'these', 'those'}
            or base & ACTION_OR_WANT):
        lexical_verb = False
    mental = bool(base & THOUGHT_SPEECH)
    # Objects can intervene: "tell the user how", "assure you that".
    if prev in {'me', 'you', 'us', 'them', 'him', 'user', 'people', 'audience'}:
        nearby = set().union(*(roots(w) for w in words[-5:-1]))
        mental = mental or bool(nearby & THOUGHT_SPEECH)
        evidence = evidence or bool(nearby & EVIDENCE)
    if prev == 'here' and before in {'show', 'shown', 'showed'}:
        evidence = True
    if (prev == 'out' and before in {'turn', 'turns', 'turned', 'find',
                                     'found', 'point', 'pointed'}):
        inference = True
    if word == 'that':
        if first:
            return 0.48
        if token.strip() == 'That':
            return -0.05
        if prev == 'now':
            return 0.35
        if evidence:
            value = -2.9
            if before in MODALS:
                value += 1.0
            if prev in {'showed', 'found', 'revealed', 'discovered'}:
                value -= 0.35
            return value
        if inference:
            return -2.0
        if mental:
            return -1.2
        if lexical_verb:
            return -0.65
        if base & FACT_NOUNS or prev in CERTAINTY:
            return -0.85
        if prev in {'is', 'was', 'be', 'are', 'were', 'been'}:
            return -0.7
        if prev == 'and':
            return -0.8 if 'that' in words[-35:] else -0.4
        if prev in {'so', 'such'}:
            return -0.15
        if prev in PREPOSITIONS:
            return -0.02
        return -0.15
    if word == 'how':
        if base & {'demonstrate', 'illustrate', 'highlight', 'showcase'}:
            return -4.8
        if evidence:
            return -3.7
        if base & {'discuss', 'explore'}:
            return -4.0
        if inference:
            return -3.0
        if prev in {'of', 'about', 'on', 'and', 'at', 'regarding', 'in', 'into', 'to'}:
            return -2.25
        if mental or lexical_verb:
            return -2.2
        if not prev or prev in '.?!,:;#"“•' or token.strip().istitle():
            return -0.4
        return -1.0
    if word == 'why':
        embedded = mental or inference or prev in {
            'reason', 'reasons', 'and', 'on', 'about'}
        return -0.85 if embedded else -0.2
    if word == 'where':
        return -0.35 if mental or evidence or inference else -0.12
    if word == 'whether':
        return -0.5 if mental or evidence or inference else -0.15
    if word == 'way':
        if prev == 'a':
            return -1.8 if before == 'such' else -1.15
        return -0.3
    if word == 'ways':
        return -0.65
    if word == 'already':
        perfect = prev in {'have', 'has', 'had', "'ve", "i've",
                           "you've", "we've", "they've"}
        return -1.65 if perfect else -0.6
    if word in {'means', 'meaning'}:
        return -1.0 if prev == 'this' else -0.18
    if word == 'что':
        return -0.65 if prev == ',' else -0.15
    if word == 'أن':
        return -0.35
    return -0.12


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    context = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = predict(token, context, first=not context)
    return (doc, (context + token)[-300:]), value

programs.haiku:
"""Clause openers after a verb of showing, finding, saying or knowing.

Layer-1 MLP component 6127 writes a strongly negative value on the word that opens an
embedded clause: "that" (or Russian "что" / Arabic "أن") and "how", as in "the data show
that ...", "the speaker demonstrates how to ...", "we believe that ...". The size depends on
what precedes the word: after findings verbs (show, find, reveal, suggest ...) it is large,
after saying/knowing verbs it is medium, after nouns like "evidence" or "belief" medium,
after "is"/"and"/"," small. Relative "that" after a noun, "that" or "how" opening a sentence
("That is...", "How many...?") are near zero.

Predicts 0 everywhere else. The word-list version explains about 36% of the variance; the
rest is the context-specific part that no short word list captures.
"""
READS = ()


def forms(*bases):
    """Each verb with its regular and common irregular endings: show, shows, showed, shown..."""
    out = set()
    for b in bases:
        out |= {b, b + "s", b + "es", b + "ed", b + "d", b + "ing", b.rstrip("e") + "ing"}
    return out


# Verbs that present a finding or result: "the data show that", "it was found that"
FINDING = forms("show", "find", "reveal", "demonstrate", "indicate", "suggest", "prove",
                "confirm", "discover", "explain", "illustrate", "describe", "observe",
                "establish", "imply", "clarify", "verify", "determine", "conclude", "report",
                "announce", "document") | {"shown", "found", "proven", "proved"}
# Verbs of saying, believing, knowing, noticing and promising
THINKING = forms("know", "believe", "think", "say", "state", "note", "mean", "see", "realize",
                 "notice", "remember", "claim", "argue", "mention", "ensure", "assume",
                 "understand", "tell", "hope", "expect", "feel", "recognize", "agree",
                 "acknowledge", "assert", "warn", "advise", "recommend", "predict", "learn",
                 "admit", "decide", "doubt", "guess", "wish", "fear", "reply", "answer",
                 "insist", "reckon", "promise", "accept", "hold", "teach", "reflect") | {
    "knew", "known", "thought", "said", "saw", "seen", "told", "meant", "felt", "held", "taught"}
# Nouns that take a that-clause: "the evidence that", "the belief that"
NOUNS = {"evidence", "fact", "belief", "idea", "hope", "sense", "assumption", "possibility",
         "proof", "finding", "suggestion", "news", "notion", "reason", "sign", "indication",
         "feeling", "thought", "opinion", "view", "argument", "realization", "claim"}
# Object pronouns after a verb: "tell me that", "show us that"
PRONOUNS = {"me", "us", "you", "him", "her", "them"}
# Words that often sit just before a that-clause: "is that", "and that"
WEAK = {"is", "was", "are", "be", "and", ",", "sure", "possible", "true", "certain", "so"}
# 'that' is also the complementizer in Russian 'что' and Arabic 'أن'
THAT_WORDS = {"that", "что", "أن"}
# a word that starts a sentence: "That is...", "How many...?" is a question, not a clause
SENTENCE_START = {"", ".", "!", "?", "\n"}


def step(carry, prefix, upstream):
    t = prefix.position
    word = prefix.token_strings[t].strip().lower()
    prev = ""
    if t > 0 and prefix.document_ids[t - 1] == prefix.document_ids[t]:
        prev = prefix.token_strings[t - 1].strip().lower()
    if word in THAT_WORDS:
        if prev in FINDING:
            return carry, -2.4
        if prev in THINKING or prev in PRONOUNS:
            return carry, -1.25
        if prev in NOUNS:
            return carry, -1.0
        if prev in WEAK:
            return carry, -0.6
        if prev in SENTENCE_START:
            return carry, 0.0
        return carry, -0.3
    if word == "how":
        if prev in FINDING:
            return carry, -3.7
        if prev in THINKING:
            return carry, -1.85
        if prev in SENTENCE_START:
            return carry, -0.3
        return carry, -1.3
    if word == "why":
        return carry, -0.5
    return carry, 0.0

programs.sol:
"""Predict short mil/mir spelling fragments rather than word meaning.

Short mil and a token completing m+il receive strong negative values;
extensions, mir/mail, and related m+ir/im fragments receive weaker ones.
Short m+iz and m+az receive positive values. Transliteration supplies related
spellings in other scripts. Chinese secret/dense/honey characters have
explicit negative cases. Longer words such as family and military are not
matched just because they contain mil.

The rounded levels approximate training activations, emphasizing positions
where the component matters. Weak accent and other ending-specific effects
are omitted to keep the main spelling pattern readable.
"""
import codecs
from functools import lru_cache
import regex
from anyascii import anyascii

READS = ()


@lru_cache(maxsize=32768)
def roman(text):
    s = anyascii(text).lower()
    return s.replace('y', 'i') if regex.search(r'\p{Arabic}', text) else s


def response(text, previous):
    word = text.strip()
    s, p = roman(word), roman(previous)
    # Related Han spellings: dense/secret, honey, and secret.
    if word in ('密', '蜜'):
        return -6.2
    if word == '秘':
        return -2.4
    if len(word) == 2 and word.endswith('密'):
        return -3.5
    if s == 'mil':
        if regex.search(r'\p{Hangul}', word):
            return -9.0
        if not word.isascii():
            return -2.6
        return -5.0 if word[0].isupper() else -6.8
    if s.endswith('mil') and len(s) in (4, 5):
        return -4.0 if len(s) == 4 else -1.1
    if s.startswith('mil'):
        tail = s[3:]
        if tail in ('a', 'e', 'o', 'u', 'y'):
            return -3.3
        if tail in ('l', 'k', 'f'):
            return -1.7
        if tail in ('es', 'ls', 'ks'):
            return -2.0
    if s.endswith('mir') and len(s) <= 4:
        return -1.7
    if s in ('mail', '-mail', 'mailing', 'mails'):
        return -1.3
    # Continuations must touch the preceding spelling, without whitespace.
    if text[:1].isspace() or regex.search(r'\p{Han}', text + previous[-1:]):
        return 0.0
    if p.endswith('mil') and s in ('a', 'e', 'i', 'o', 'u'):
        return -8.0
    if p.endswith('mi'):
        if s.startswith('l') and len(s) <= 3:
            return -4.7
        if s == 'r' or (s.startswith('r') and regex.search(r'\p{Katakana}', text)):
            return -4.0
    if not p.endswith('m'):
        return 0.0
    if s.startswith('il'):
        tail = s[2:]
        if previous[-1:] == 'm' and word.startswith('IL'):
            return -1.4
        if regex.search(r'\p{Arabic}', text):
            return -3.8
        if not tail:
            return -7.7
        if tail in ('a', 'e', 'la', 'le'):
            return -7.0
        if tail in ('i', 'l', 'm'):
            return -4.0
        if len(tail) <= 3:
            return -3.0
    if s in ('iz', 'izi', 'izu', 'izin'):
        return 5.0
    if s == 'az':
        return 3.5
    if s.startswith('ir') and len(s) <= 5:
        return -2.6 if len(s) == 2 else -1.5
    if s.startswith('im') and len(s) <= 4:
        return -2.8
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, pending = '', b''
    else:
        _, previous, pending = carry
    # A character may be split across several byte-level tokens.
    raw = pending + prefix.token_bytes[-1]
    text, n = codecs.utf_8_decode(raw, 'ignore', False)
    value = response(text, previous)
    return (doc, (previous + text)[-8:], raw[n:]), value

"""Sparse surface-form approximation of a document/format-boundary component.

This is a partial explanation: ordinary in-document tokens are set to zero.
Rules cover numeric openings (a run of 1s followed by 2s), code and quotation
openings, horizontal underscore rules, scientific headings and page metadata.
Opening responses persist while the initial token is repeated. Separator
responses depend on their length and whether they follow TABLE/EXAMPLE labels.
The remaining small, token-specific fluctuations are not modeled.
"""
import re

READS = ()
NUMBERED_HEADING = re.compile(
    r'(?:Proof of )?(?:Theorem|Lemma|Corollary|Proposition|Algorithm|'
    r'Case|FIGURE)\s+(\d+(?:\.\d+)*)\.?$'
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, opening, underscores, line = 0, '', 0, ''
        first, repeating = s, True
    else:
        _, position, opening, underscores, line, first, repeating = carry
        repeating = repeating and s == first
    if position < 12:
        opening += s
    value = 0.0
    # Opening-token biases also apply to an uninterrupted initial repetition.
    if repeating:
        value = -0.20 if s[:1].isspace() else -0.08
        word = s.strip()
        if word in {'I', 'my', 'My'}:
            value = -0.7
        if len(s) > 1 and s[0] in '"“' and s[1].isalpha():
            value = 1.6
        elif s == '"':
            value = 0.8
        if s == '<!':
            value = 2.56
        elif s == '<img':
            value = 1.8
        if word == '0':
            value = -0.65
        if s.startswith(' .') and word == '.':
            value = -1.5 if '\n' in s else -2.6
        if s.startswith(('"""', "'''")):
            value = -2.7 if '\n' in s else -0.85
        if s.startswith('/*'):
            value = -1.3 if '\n' in s else -0.57
        if s.lstrip().startswith('//'):
            value = -0.75
        if word == 'def':
            value = -3.15
        elif word in {'class', 'function'}:
            value = -1.0
        elif word == 'print':
            value = -1.5
        if s == '<|endoftext|>':
            value = 1.88
        if s == '\r':
            value = -1.6
        if s == '··':
            value = -0.98
        if s == r'\t':
            value = 2.25
        elif s == r'\"':
            value = 1.77
    # An unusually strong response to the initial 1-to-2 numeric transition.
    number = re.fullmatch(r'(1+)(2{1,3})', opening)
    if position < 12 and s == '2' and number:
        amplitude = (3.1, 1.2, 0.15)[len(number[2]) - 1]
        value = amplitude / (1 + 0.2 * (len(number[1]) - 1))
    # Horizontal separators; their final short chunks can be the strongest.
    if s and not s.strip('_'):
        size = len(s)
        if size == 2 and underscores >= 36:
            value = 2.0 if underscores < 64 else 4.3
        elif size == 12 and underscores == 32:
            value = 1.0
        elif size >= 32 and not repeating:
            value = 0.4 if underscores == 0 else 1.2
        caption = re.search(r'\b(?:TABLE|EXAMPLE)\s+[0-9IVXLCDM]+_*$', line)
        if caption:
            if size == 2 and underscores >= 36:
                value = 4.7 if underscores < 64 else 6.2
            elif size >= 32:
                value = 1.7
            elif size == 8 and underscores >= 64:
                value = 1.3
        underscores += size
    else:
        underscores = 0
    text = line + s
    # Recognizable page furniture: counts, pagination and question separators.
    if s.strip() == '#####' and position > 0:
        value = 0.35
    if re.search(r'(?:^|\()\d{2,}\s+words$', text, re.I):
        value = -1.4
    elif text.strip(' #*') == 'Words':
        value = -1.4
    if re.fullmatch(r'[# ]*Page\s*\d+\s*/', text):
        value = 1.6
    if text.endswith('Challenge Level'):
        value = -0.31
    if re.fullmatch(r'Step\s*Hyp\s*Ref\s+Expression', text):
        value = -1.5
    if text == '#pragma once':
        value = 0.79
    if len(s.strip()) >= 6 and not s.strip(' :'):
        value = 1.28
    # Scientific headings and their terminating newline.
    if text.lower().strip(' #*').endswith('author contributions'):
        value = 5.1
    elif text.strip() == 'AUTHOR CONTRIBUT':
        value = 2.2
    if s in {'\n', '.\n'}:
        match = NUMBERED_HEADING.fullmatch(line.strip(' #*'))
        if match:
            value = 0.4 if '.' in match[1] else 1.4
    line = text.rsplit('\n', 1)[-1][-100:]
    return (doc, position + 1, opening, underscores, line, first, repeating), value

programs.haiku:
"""Layer-1 MLP unit 6130 (down_proj) -- a weak, diffuse "word-piece continuation" detector.

It fires on tokens that continue a word already begun in the previous token (a
letters-only piece with no leading space, after a letters-only piece), i.e. the
second and later pieces of a word split by the tokenizer. Its size depends on the
script: strongest for Arabic and Cyrillic continuations, weaker for Latin, zero for
CJK. Vowel-final Cyrillic/Latin pieces (typical inflection endings such as -а, -ов,
-ы, -е, -o, -a) get a bit more. Everything else predicts 0.
"""
import unicodedata

READS = ()

VOWELS = set("aeiouyаеиоуыэюяáéíóúàèìòùãõ")


def _letters(s):
    return len(s) > 0 and all(unicodedata.category(c).startswith("L") for c in s)


def _script(s):
    name = unicodedata.name(s[0], "")
    if "CYRILLIC" in name:
        return "cyr"
    if "ARABIC" in name:
        return "arab"
    if "LATIN" in name:
        return "lat"
    if "CJK" in name or "HIRAGANA" in name or "KATAKANA" in name:
        return "cjk"
    return "other"


SCRIPT_WEIGHT = {"cyr": 0.09, "arab": 0.35, "lat": 0.03, "other": 0.03, "cjk": 0.0}


def step(carry, prefix, upstream):
    if prefix.position == 0 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return None, 0.0
    cur = prefix.token_strings[-1]
    prev = prefix.token_strings[-2]
    continues_word = _letters(cur) and _letters(prev) and not prev.startswith(" ")
    if not continues_word:
        return None, 0.0
    value = SCRIPT_WEIGHT[_script(cur)]
    if cur[-1].lower() in VOWELS:
        value += 0.10
    return None, value


if __name__ == "__main__":
    print("run via eval; see docstring")

programs.sol:
"""Syntactic landmarks near the start of a parenthesized phrase.

The signal is strongest on example abbreviations, cross-references, logical
connectives and punctuation, not on ordinary words or digits. It fades as the
phrase gets longer. The same rules cover code arguments; function keywords,
quotes, lists and the beginning of a function body receive extra weight.
Brackets are counted even in quoted text; this is not a language parser.
"""
import math

READS = ()
REFERENCES = set('''fig figs figure figures tab table tables eq equation
    equations section sec appendix theorem lemma'''.split())
CONNECTIVES = set('''as and or for not since if when while because also see cf
    versus vs aka formerly that is namely including especially called case'''.split())
FUNCTIONS = {'function', 'func', 'lambda'}
LISP_FORMS = {'(let', '(if', '(define', '(lambda'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        depth, squares, age, square_age, previous, function_age = (
            0, 0, 999, 999, '', 999)
    else:
        _, depth, squares, age, square_age, previous, function_age = carry
    token = prefix.token_strings[-1]
    s = token.strip()
    word = s.lower()
    near = math.exp(-max(0, age - 3) / 3) if depth else 0.0
    first = math.exp(-max(0, age - 1)) if depth else 0.0
    quote = any(c in '\"\'`“‘' for c in s)
    closes = any(c in ')]}' for c in s)
    operator = bool(s) and all(c in '=+*/^|<>!~' for c in s)
    base, value = 0.0, 0.0

    if s in {'.g', '.e'}:
        base = 5.51 if s == '.g' else 4.66
    elif previous in {'.g', '.e'} and s in {'.', '.,'}:
        base = 2.49
    elif word in REFERENCES:
        value = 2.57 * first
    elif word in CONNECTIVES:
        value = 1.15 * first
    elif word in FUNCTIONS:
        value = 1.78 if depth and age <= 24 else 0.0
    elif word in {'right', 'frac', 'sqrt'} and previous.endswith('\\'):
        base = 2.19
    elif quote and not closes:
        base = 1.20 + (2.41 if previous.lower() == 'the' else 0.0)
    elif s and all(c in '.,' for c in s):
        base = 0.77 if s == ',' else 0.67
    elif s and all(c in ':=' for c in s) and ':' in s:
        base = 1.10
    elif s == ';':
        base = 1.09
    elif operator:
        base = 1.94 if s == '=>' else 0.65
        if squares:
            value = 0.31 * math.exp(-max(0, square_age - 2) / 3)
    elif s and all(c in '-–—−' for c in s):
        base = 0.57
    elif '{' in s:
        base = 1.34
    elif '[' in s:
        base = 1.23
    elif '(' in s:
        base = 0.14
    elif len(s) > 1 and s.isalpha():
        value = 0.13 * first
    elif not s:
        base = 0.17

    # Recognizable parenthetical labels and code constructions.
    if word == 'example' and previous.lower() == 'for':
        base += 3.76
    if word in {'cite', 'ref', 'eqref', 'autoref'} and previous.endswith('\\'):
        base += 2.99
    if word in {'http', 'https', '/#', '#', '/'}:
        value += 1.13 * first
    if word == 'etc' and depth:
        value += 1.29
    if word == 'respectively':
        value += 0.88 if previous == ',' else 0.16
    alias = ((word == '-called' and previous.lower() == 'so') or
             (word == 'as' and previous.lower() == 'known') or
             (word == '/or' and previous.lower() == 'and'))
    if alias:
        base += 2.25
    if s == '\\':
        base += 0.66
    if '(' in s and quote and not closes:
        value += 0.83
    if word == '(function' or word in LISP_FORMS:
        value += 3.28
    if '{' in s and function_age <= 16:
        value += 0.72
    value += base * near

    if word in FUNCTIONS or word in {'(function', '(lambda'}:
        function_age = 0
    for char in token:
        if char in '(（':
            depth += 1
            age = 0
        elif char in ')）':
            depth = max(0, depth - 1)
        elif char == '[':
            squares += 1
            square_age = 0
        elif char == ']':
            squares = max(0, squares - 1)
    return (doc, depth, squares, age + 1, square_age + 1,
            s, function_age + 1), value

"""Sparse spelling and formatting cues, not a general semantic detector.

The largest rules recognize a split long-s, split Korean syllables with
marked final consonants, hidden-email labels, and LaTeX operator names.
Smaller rules cover temporal phrases, Android graphics imports, and initial
runs of identical tokens. Korean responses are only a phonetic approximation:
individual syllables can have very different strengths within each group.
"""
import unicodedata

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    fresh = carry is None or carry[0] != doc
    tail = b'' if fresh else carry[1]
    b = prefix.token_bytes[-1]
    s = b.decode('utf-8', errors='replace')
