            initial = 1.7 if s == 'use' else 0.9
        elif s == 'def':
            initial = -3.2
        elif s and set(s) <= set('·⎯'):
            initial = -1.29 if '·' in s else -0.89
    value = initial if first is not None else 0.0

    # Familiar multi-token labels and constructions.
    if s.strip() == 'protected' and b'[email' in tail[-24:]:
        value = 4.3
    elif s == 'name' and tail.endswith(b'operator'):
        value = -1.2
    elif s == '{' and tail.endswith(b'operatorname'):
        value = -0.32
    elif s == ' on':
        if tail.lower().endswith(b'early'):
            value = 1.8
        elif tail.lower().endswith(b'later'):
            value = 0.6
    elif s == '.graphics' and tail.endswith(b'android'):
        value = 1.7
    elif s == 'most' and tail.endswith(b'inner'):
        value = 1.5

    # A byte fragment differs from a whole-character token.
    if len(b) == 1 and 0x80 <= b[0] < 0xc0:
        ch = joined.decode('utf-8', errors='replace')[-1]
        name = unicodedata.name(ch, '')
        value = 0.1
        if joined.endswith('ſ'.encode()):
            value = 2.65
        elif name.startswith('HANGUL SYLLABLE'):
            coda = (ord(ch) - 0xac00) % 28
            if coda in (9, 11):      # ㄺ, ㄼ: rieul + stop clusters
                value = 3.6
            elif coda in (2, 5, 7, 15, 22, 25, 26, 27):
                # Marked codas: ㄲ ㄵ ㄷ ㅀ ㅈ ㅌ ㅍ ㅎ.
                value = 1.8
            elif coda in (17, 19):   # ㅂ, ㅅ
                value = 0.6
            else:
                value = 0.12
        elif name in ('ETHIOPIC WORDSPACE', 'ETHIOPIC FULL STOP'):
            value = 1.6
        elif name.startswith('LATIN'):
            value = 0.3
    elif s == 'ſ':
        value = 0.19

    return (doc, joined[-64:], first, initial), float(value)

"""Approximate a question-ending / chat-turn-ending response.

Question punctuation and Chinese interrogative particles give positive values.
Newlines after a chat end marker are another strong cue, especially following a
short user query. Early-document lines and Han text give weaker positive cues.
Tiny formatting rules cover an initial 'Title:' label and double middle dots.
It tracks only the speaker, lengths, and a few flags; smaller lexical variation
is left unexplained. State resets at document and end-of-text boundaries.
"""
import regex

READS = ()
HAN = regex.compile(r'\p{Script=Han}')
HOW = {'如何', '怎么', '怎麼', '怎样', '怎樣', '怎', '怎么办'}
WHAT = {'是什么', '是什麼', '什么意思', '什麼意思', '有哪些'}
WH = {'什么', '什麼', '哪里', '哪裡', '哪个', '哪個', '哪些', '哪',
      '为何', '為何', '为什么', '為什麼', '是否', '有什么', '有什麼'}
PARTICLES = {'吗': 1.64, '嗎': 1.64, '呢': .90, '么': 1.02,
             '麽': .60, '吧': .40, '啊': .40, '嘛': 1.25}
QUERY = HOW | WHAT | WH | {'吗', '嗎'}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry['doc'] != doc:
        carry = dict(doc=doc, prev='', speaker='', length=0, position=0,
                     han=False, query=False, tail='', lines=0)
    s = carry
    word = token.strip()
    early = 1 / (1 + s['position'] / 20)
    short = 1 / (1 + s['length'] / 20)
    user = s['speaker'] == 'user'
    value = .001
    if token and not token.strip('\r\n'):
        if s['prev'] == '<|im_end|>':
            value += .8 + .7 * early + (.75 * user - .25) * short
            value += .2 * s['han'] + 1.3 * s['query']
            value += .2 * (s['tail'] in ('?', '？'))
            value -= .2 * (s['tail'] in ('.', '。'))
        elif s['length'] == 0 and s['speaker']:
            value -= .06
        else:
            value += .02 + .1 * (s['lines'] == 0) + .35 * s['han'] * early
    if any(c in token for c in '?？؟'):
        if any(c in token for c in ':;=<>'):
            value -= .07
        else:
            value += .15 + .82 * early + .87 * user * short
            value += .4 * ('?' not in token)
            value += .18 * (token.count('\n') == 1)
            value -= .09 * (token.count('\n') > 1)
            value -= .17 * any(c in token for c in '\"\'”’」')
            value -= .19 * (')' in token) + .1 * token.startswith(' ')
    value += PARTICLES.get(word, 0.)
    if word in HOW:
        value += .63
    elif word in WHAT:
        value += 1.59
    elif word in WH:
        value += .25

    if token == 'Title' and s['position'] == 0:
        value += .52
    if token == ':' and s['prev'] == 'Title' and s['position'] < 4:
        value += 2.63
    if token == '··':
        value -= .59

    s['position'] += 1
    if token == '<|endoftext|>' or s['prev'] == '<|im_start|>':
        s.update(speaker=token if s['prev'] == '<|im_start|>' else '',
                 length=0, han=False, query=False, tail='', lines=0)
        if token == '<|endoftext|>':
            s['position'] = 0
    elif token not in ('<|im_start|>', '<|im_end|>'):
        s['length'] += 1
        s['han'] |= bool(HAN.search(token))
        s['query'] |= word in QUERY
        if word:
            s['tail'] = word
        s['lines'] += token.count('\n')
    s['prev'] = token
    return s, float(value)

programs.haiku:
"""Question-ending detector for layers.1.mlp.down_proj:6134.

The component is quiet on almost every token. It switches on at the points where a
user has just finished asking something, where an answer is expected next:
  * the newline that closes a chat turn (<|im_end|> then a newline), strongest;
  * question marks ('?', '？', and '?' fused with a newline), stronger after Chinese text;
  * Chinese question particles (吗 嗎 么 呢 吧 啊) and question words (如何 怎么 哪 何).
Plain English question words (What, How, Can) do not drive it. Everything else is ~0.
"""

READS = ()

TURN_END_NEWLINE = 0.9
QUESTION_MARK_LATIN = 0.3
QUESTION_MARK_CJK = 0.7
QUESTION_PARTICLE = 1.0
QUESTION_WORD = 0.7

PARTICLES = {"吗", "嗎", "么", "麽", "呢", "吧", "啊", "嘛"}
QUESTION_WORDS = {"如何", "怎么", "哪", "何", "区别", "有哪些", "什么意思", "是什么", "怎么办"}


def is_cjk(text):
    return any("一" <= ch <= "鿿" for ch in text)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    previous = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if token == "\n" and previous == "<|im_end|>":
        return None, TURN_END_NEWLINE
    if token in PARTICLES:
        return None, QUESTION_PARTICLE
    if token in QUESTION_WORDS:
        return None, QUESTION_WORD
    if "？" in token:
        return None, QUESTION_MARK_CJK
    if "?" in token:
        return None, QUESTION_MARK_CJK if is_cjk(previous) else QUESTION_MARK_LATIN
    return None, 0.0

"""Infinitive / purpose "to" detector (layers.1.mlp.down_proj, component 6135).

The component fires on the word "to" when "to" opens an infinitive or purpose phrase,
where a verb is expected next: "is to", "need to", "and to", "going to", "order to",
"like to", "To copy ...". It stays near zero when "to" is a preposition: "due to",
"according to", "compared to", "led to", "from 5 to 10", "convert to", "reduced to".
Adjective complements ("able to", "easy to") are weak. German "zu" (its infinitive marker)
is a steady 0.65. Nearly every other token is ~0.

The program reads only the word before "to" and a few words before that, which the
model's input also shows. A document boundary resets the context.
"""

READS = ()

TO_WORDS = {" to", " To", "To"}

# "to" after these is a preposition (direction, reference, cause): silent
PREPOSITION_BEFORE = {
    "due", "according", "compared", "related", "relating", "respect", "equal",
    "led", "lead", "leads", "leading", "up", "back", "return", "close", "similar",
}
# "to" in a range or conversion ("from 2 to 5", "convert to", "reduced to"): silent
RANGE_WORDS = {
    "from", "convert", "converted", "reduce", "reduced", "switch", "switched",
    "transition", "change", "changed", "turn", "turned",
}
# "to" after these: ability / adjective complements ("able to", "easy to"): weak
ABILITY_BEFORE = {"able", "unable", "easy", "possible", "difficult", "hard", "ability", "capable"}
# "to" after these: infinitive or clause start (punctuation, conjunction, "is", "order to"): strong
INFINITIVE_BEFORE = {
    "is", "was", "are", "and", "or", "but", "not", "like", "order", "going", "if",
    ",", ".", "\n", "-",
}
# "to" after these: verbs of wanting, needing, using: medium
VERB_BEFORE = {
    "want", "wants", "wanted", "need", "needs", "needed", "have", "has", "required",
    "decided", "try", "tried", "trying", "used", "designed", "aim", "goal",
}
NOUN_ENDINGS = ("tion", "ment", "ity", "ness", "ance", "ence", "ism", "ure")


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token == " zu":
        return carry, 0.65
    if token not in TO_WORDS:
        return carry, 0.0
    if prefix.position == 0 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, 0.4
    before = prefix.token_strings[-2].strip()
    window = {w.strip() for w in prefix.token_strings[-5:-1]}
    if before in PREPOSITION_BEFORE or window & RANGE_WORDS:
        value = 0.0
    elif before in ABILITY_BEFORE:
        value = 0.15
    elif before in INFINITIVE_BEFORE:
        value = 0.95
    elif before in VERB_BEFORE:
        value = 0.5
    elif before.endswith(NOUN_ENDINGS):
        value = 0.3
    else:
        value = 0.45
    return carry, value

programs.sol:
"""Approximate a layout/diagram-syntax response with a shallow text recognizer.

The large training responses cluster around typesetting and drawing controls;
recognize those grammatical roles rather than looking up arbitrary token IDs.

TeX lengths, column specifications, arrow options and drawing operators get
negative amplitudes; coordinate connections get smaller negative amplitudes.
Clock suffixes and stretchable spacing get positive amplitudes. These are
empirical averages, not a complete TeX parser or a model of the small residual
lexical responses. Keep only the last 256 characters, resetting per document.
"""
import re

READS = ()
# Unit: (ordinary attached suffix, TeX spacing/sizing parameter).
LENGTHS = {
    'cm': (-0.5, -5.2), 'mm': (0.0, -6.1), 'em': (-1.3, -4.8),
    'ex': (-0.5, -6.6), 'pt': (-1.9, -6.7), 'pc': (-0.7, -6.0),
    'in': (-0.6, -1.0),
}
# Alignment: (single column, several columns in one token).
COLUMNS = {'l': (-2.9, -4.4), 'c': (-6.4, -9.1), 'r': (-3.1, -5.9)}
COLORS = {'black', 'white', 'blue', 'red', 'green', 'yellow', 'cyan',
          'magenta', 'gray', 'orange', 'purple', 'brown'}
STYLES = {'very', 'thick', 'thin', 'dashed', 'dotted', 'anchor', 'above',
          'below', 'left', 'right', 'fill', 'shift', 'scale', 'radius',
          'font', 'rotate', 'align'}
DRAW = r'\\(?:draw|filldraw|fill|path|node)\b([^;]*)$'


def coordinates(text):
    m = re.search(r'\([0-9a-z+*/., ^√\-]{1,45}\)$', text)
    return bool(m and ',' in m[0])


def response(h, s, age):
    w = s.strip()
    if not w or w.isdigit():
        return -0.002
    # Typography and numerical lengths.
    if w in LENGTHS and h and h[-1].isdigit():
        if re.search(DRAW, h):
            return -5.5
        if re.search(r'\\(?:arrow|raisebox|setlength)\b[\s\S]{0,80}$', h):
            return -9.2
        if re.search(r'\\documentclass\[[^\]]*$', h):
            return -4.5
        if re.search(r'\\\[(?:above|below|left|right)[^\]]*$', h):
            return -4.7
        if re.search(r'\\(?:hspace|vspace|rule|parbox|resizebox|kern|hskip|'
                     r'vskip|includegraphics|xymatrix)\b[^\n]{0,85}$', h):
            return LENGTHS[w][1]
        if re.search(r'(?:\\\\\[|\b(?:width|height)=\"?)[^}\]\n]{0,15}$', h):
            return LENGTHS[w][1]
        return 0.1 if s[0].isspace() else LENGTHS[w][0]
    if w in {'am', 'pm'} and h and h[-1].isdigit():
        return -0.04 if s[0].isspace() else (1.4 if w == 'am' else 0.52)
    if s == 'fill' and h.endswith(('\\h', '\\v')):
        return 1.0
    if s in {'[-', '['} and h.endswith('\\rule'):
        return -4.0

    # The column-format argument of a TeX array/tabular environment.
    if s == '}{' and re.search(r'\\begin\{(?:array|tabular)\*?$', h):
        return -2.0
    if re.fullmatch('[lcr]{1,6}', w) or w in {'|', '@'}:
        starts = list(re.finditer(r'\\begin\{(?:array|tabular)\*?\}\{', h))
        if starts:
            depth, tail = 1, h[starts[-1].end():]
            for ch in tail:
                depth += (ch == '{') - (ch == '}')
                if depth == 0:
                    break
            if depth > 0 and not any(ch in tail for ch in '&$\n'):
                if w == '|':
                    return -2.0
                if w == '@':
                    return -3.5
                return COLUMNS[w[0]][len(w) > 1]

    # XY-pic and TikZ commutative-diagram arrow directions and labels.
    if re.search(r'\\ar\s*(?:@[^\n]{0,20})?\[\s*[lrud]*$', h):
        if re.fullmatch('[lrud]{1,6}', w):
            return -5.7 if h[-1] in 'lrud' else -10.9
        if w.startswith(']'):
            return -4.5 if len(w) > 1 else -3.3
    if re.search(r'\\ar\s*$', h):
        if w.startswith('['):
            return -8.9 if w == '[' else -10.9
        if w == '@':
            return -8.6
    if re.search(r'\\ar[^\n]{1,30}\]$', h) and w.startswith(('_', '^')):
        return -3.5
    if w.startswith('[') and re.search(r'\\arrow\s*$', h):
        return -8.7
    if re.search(r'\\arrow[^;]{0,100}\]\{$', h):
        if re.fullmatch('[lrud]{1,6}', w):
            return -6.2
    if w == 'ar' and h.endswith('\\'):
        return -1.5
    if s == 'atrix' and h.endswith('\\xym'):
        return -4.0

    # Figure placement, image options, and PGF property handlers.
    if re.search(r'\\begin\{(?:figure|table)\*?\}\[$', h):
        if w in {'h', 't', 'b', 'p', 'ht', 'htbp', 'H'}:
            return -7.4 if len(w) > 1 else -4.4
    if s.startswith('[') and h.endswith('\\includegraphics'):
        return -5.5
    if w in {'width', 'height'} and h.endswith('\\includegraphics['):
        return -3.6
    if s.startswith('=') and re.search(r'(?:width|height)$', h):
        if '\\includegraphics[' in h[-100:] or re.search(r'\)\{\w+$', h):
            return -2.2
    if w in {'code', 'style'} and h.endswith('/.'):
        return -8.4
    if s == '/.' and re.search(r'\\(?:tikzset|def)\b', h):
        return -6.2

    # Unfinished TikZ paths: options, shapes, points, and connections.
    drawing = re.search(DRAW, h)
    option = re.search(r'(?:node|\\draw|\\filldraw|\\fill|\\path)\s*\[[^\]]*$', h)
    if option and w in STYLES:
        return -4.9
    if drawing:
        tail = drawing[1]
        if w.startswith('['):
            if re.search(r'\b(?:circle|pic)\s*$', h):
                return -5.3
            if not tail.strip():
                return -9.2 if w == '[' else -7.3
        if tail.rfind('[') > tail.rfind(']'):
            if w in COLORS:
                return -4.9
            if w.startswith('='):
                return -2.5
            if w == ']':
                return -1.3
        if w in {'--', '..', '++'}:
            return -7.0
        if w in {'circle', 'rectangle', 'ellipse', 'arc', 'pic'}:
            return -8.2
        if w == 'cycle':
            return -10.5
        if w == 'at':
            return -8.7
        if w.startswith('('):
            return -5.6
        if w == ')':
            return -3.0
    if s == 'draw' and re.search(r'\\(?:fill)?$', h):
        return -2.8
    if w == 'pair' and re.search(r'\[asy\]|defaultpen|unitsize|; pair ', h):
        return -8.6
    if s == 'pen' and h.endswith('default'):
        return -12.5

    # Coordinate joins in Asymptote or in ordinary mathematical prose.
    if s == ')--' and re.search(r'\([^()]*\d[^()]*,[^()]*$', h):
        return -8.0
    if s == '(' and re.search(r'\([0-9., +*/^\-]+\)--$', h):
        return -8.3
    if w == 'cycle' and h.rstrip().endswith('--'):
        return -8.4
    if w == 'controls' and h.endswith(' ..'):
        return -11.5
    if s == ' ..' and coordinates(h):
        return -4.4
    if w == 'to' and coordinates(h):
        return -0.94
    if s in {' (', '('}:
        m = re.search(r'\b(at|to|from|between)\s*$', h)
        if m and coordinates(h[:m.start()].rstrip()):
            return -1.9
        if m and m[1] == 'at':
            return -3.0 if age < 16 else -0.8
    if s == ')(' and h and h[-1].isdigit():
        return -0.3
    return -0.002


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        h, age = '', 0
    else:
        _, h, age = carry
    s = prefix.token_strings[-1]
    return (doc, (h + s)[-256:], age + 1), response(h, s, age)

"""A start-of-document response, graded by the first token's writing system.

The large negative activation is almost confined to a document's first token.
Alphabetic text elicits more of it than Han text, numbers or whitespace;
Cyrillic, Arabic and Thai elicit particularly strong responses.  English
articles and grammatical forms refine this coarse estimate.  Later positions
are approximated as silent, apart from explicit conversation delimiters.
The constants are coarse group averages, not a token-by-token lookup.
"""
import regex

READS = ()

SCRIPTS = [
    ('Han', -2.8), ('Cyrillic', -17.9), ('Arabic', -24.4),
    ('Thai', -26.1), ('Greek', -13.0), ('Hangul', -14.8),
    ('Hiragana', -6.1), ('Katakana', -11.4), ('Hebrew', -17.0),
    ('Armenian', -25.0), ('Devanagari', -18.0),
]
SCRIPT_TESTS = [(name, regex.compile(r'\p{Script=' + name + '}'), value)
                for name, value in SCRIPTS]
PREPOSITIONS = set('of to in on for with at from by into over under'.split())
COPULAS = set('is are was were be been being am'.split())
POSSESSIVES = set('my your his her its our their'.split())
PLURAL_PRONOUNS = set('we they you'.split())
SINGULAR_PRONOUNS = set('he she it'.split())
QUESTIONS = set('how what why who where when which'.split())
DECLARATIONS = set(
    'package class namespace struct enum interface const let int function'.split()
)
IMPORTS = set('import include using require'.split())


def initial_value(token):
    word = token.strip()
    space = token.startswith(' ')
    if not word:
        if '\n' in token or '\r' in token:
            return -0.6 if not space else -2.0
        if token.strip('\t') == '':
            return 1.9 if len(token) == 1 else -2.3
        return -3.8 if len(token) == 1 else -6.1
    if word.startswith('<|') or word in {
        '<think>', '</think>', '<tool_call>', '</tool_call>',
        '<tool_response>', '</tool_response>',
    }:
        return -7.3
    if word.isdigit():
        return -1.7 if word == '0' else -4.6
    letter = next((c for c in word if c.isalpha()), word[0])
    for script, test, value in SCRIPT_TESTS:
        if test.fullmatch(letter):
            if script == 'Cyrillic':
                if word.isupper() and len(word) == 1 and not space:
                    return -24.5
                return -14.8 if space else -17.2
            if script == 'Arabic':
                return -22.0 if space else -28.7 if len(word) == 1 else -23.5
            if script == 'Greek':
                return -8.0 if space else -16.9 if word.isupper() else -12.9
            return value
    if not any(c.isalpha() for c in word):
        if word in ',，、:：;；':
            return -1.9
        if word and set(word) == {'#'}:
            return -8.0
        if word == '.':
            return -5.8
        if word in ')]}':
            return -1.8
        return -4.1
    low = word.lower()
    if low == 'the':
        return -12.0
    if word in DECLARATIONS:
        return -0.2 if not space else -3.0
    if low in IMPORTS and not space:
        return -4.0
    if low in POSSESSIVES:
        return -11.5
    if low in PLURAL_PRONOUNS:
        return -9.3
    if low in SINGULAR_PRONOUNS:
        return -7.5 if low == 'it' and space else -4.3
    if low in COPULAS:
        return -9.0 if low in {'are', 'was', 'were', 'been'} else -5.4
    if low == 'an':
        return -10.0
    if low == 'this':
        return -8.8
    if low == 'that':
        return -5.5
    if low in {'these', 'those'}:
        return -11.0
    if low in {'as', 'so', 'then', 'but'}:
        return -4.3
    if low in PREPOSITIONS:
        return -9.0 if space or word.istitle() else -6.7
    if low in QUESTIONS and word.istitle():
        return -12.5
    if word.isupper():
        return -4.3 if space else -6.5
    if word.istitle():
        return -6.7
    return -8.0 if space else -5.3


def step(carry, prefix, upstream):
    first = (prefix.position == 0 or
             prefix.document_ids[-1] != prefix.document_ids[-2])
    token = prefix.token_strings[-1]
    if first:
        value = initial_value(token)
    else:
        value = {'</tool_call>': -0.7, '</tool_response>': 0.37,
                 '<think>': 0.3, '<tool_call>': -0.16}.get(token, 0.0)
    return None, value

programs.haiku:
"""Layer-1 MLP down_proj component 6138: a document-start detector.

The component is silent inside a document and fires only on a document's first
token (position 0 after a document boundary, where attention can see nothing but
the token itself). There its activation is negative, and its size is set by what
kind of token it is:

  * letters of a non-Latin alphabet: Arabic and Thai strongly negative (about -27),
    Cyrillic, Greek, Hangul and katakana moderately so (about -16);
  * Latin-script words: -5 to -8 (a word with a leading space or a capital letter
    is more negative than a bare lowercase fragment);
  * special tokens such as <|im_start|>: about -7;
  * digits and punctuation: mildly negative, about -4;
  * whitespace and CJK characters: close to zero.

Everywhere else the prediction is 0.
"""

import unicodedata

READS = ()

ARABIC_THAI = -27.0
OTHER_ALPHABET = -16.0
LATIN_SPACE_WORD = -8.0
LATIN_CAP_WORD = -7.5
LATIN_WORD = -5.4
SPECIAL = -7.2
DIGIT_OR_PUNCT = -4.1
WHITESPACE = -3.0
CJK = -2.8
BYTE_FRAGMENT = -7.3


def _script(ch):
    try:
        return unicodedata.name(ch).split()[0]
    except ValueError:
        return ""


def doc_start_value(s):
    """Predicted activation for a token that opens a document, given its decoded text."""
    if s.startswith("<|"):
        return SPECIAL
    if "�" in s:
        return BYTE_FRAGMENT
    body = s.strip()
    if not body:
        return WHITESPACE
    letters = [c for c in body if c.isalpha()]
    if not letters:
        return DIGIT_OR_PUNCT
    script = _script(letters[0])
    if script == "LATIN":
        if s[0] == " ":
            return LATIN_SPACE_WORD
        if s[0].isupper():
            return LATIN_CAP_WORD
        return LATIN_WORD
    if script in ("CJK", "HIRAGANA", "IDEOGRAPHIC"):
        return CJK
    if script in ("ARABIC", "THAI"):
        return ARABIC_THAI
    return OTHER_ALPHABET


def step(carry, prefix, upstream):
    t = prefix.position
    if t > 0 and prefix.document_ids[t] == prefix.document_ids[t - 1]:
        return carry, 0.0
    return carry, doc_start_value(prefix.token_strings[t])

programs.sol:
"""Approximate a soft long-token detector using spelling, not token identity.

English-like tokens are measured both whole and after removing an ordinary
inflectional ending. The response grows fastest for five-to-eight-letter
stems. Han sequences, other scripts, spacing and punctuation have separate
length scales. Newlines reduce the spacing response; markup is near zero.
Document starts receive a negative offset, followed by a small second-token
rebound. This state resets at document boundaries. No learned vocabulary
lookup is used.
"""
from functools import lru_cache
import re
import regex

READS = ()
HAN = regex.compile(r'\p{Script=Han}')
MARKUP = re.compile(r'</?(?:tool_\w+|think)>|<\|[^>]+\|>')


def ramp(size, start, stop):
    """How much of a length lies between these two thresholds?"""
    return max(0, min(size, stop) - start)


@lru_cache(maxsize=16384)
def response(text):
    word = text.strip()
    n = len(word)
    if MARKUP.fullmatch(word):
        return 0.02
    if text.isspace():
        n = len(text)
        value = (0.209 * ramp(n, 6, 12) + 0.083 * ramp(n, 12, 24)
                 - 0.023 * ramp(n, 24, 64)
                 - 0.072 * ramp(n, 6, 64) * ('\n' in text))
        return max(0.0, value)
    han = len(HAN.findall(word))
    if han:
        value = 0.494 * ramp(han, 1, 2) + 0.923 * ramp(han, 2, 4)
    elif word.isascii() and any(c.isalpha() for c in word):
        stem = word.lower()
        for ending in ('ing', 'ed', 'es', 's'):
            if stem.endswith(ending) and n > len(ending) + 2:
                stem = stem[:-len(ending)]
                break
        value = (-0.041 * ramp(n, 4, 5) + 0.240 * ramp(n, 5, 7)
                 + 0.045 * ramp(n, 7, 16)
                 + 0.205 * ramp(len(stem), 4, 8)
                 + 0.064 * ramp(len(stem), 8, 16)
                 - 0.162 * (word.lower().endswith('ly') and n > 4))
    elif any(c.isalpha() for c in word):
        size = len(word.encode('utf-8'))
        value = (0.074 * ramp(size, 6, 12) + 0.030 * ramp(size, 12, 24)
                 + 0.162 * ramp(n, 4, 8))
    elif word and not any(c.isalnum() for c in word):
        value = 0.182 * ramp(n, 4, 16)
    else:
        value = 0.0
    return value - 0.008


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        age = 0
    else:
        age = min(carry[1] + 1, 2)
    value = response(prefix.token_strings[-1])
    if age == 0:
        value -= 1.27
    elif age == 1:
        value += 0.15
    return (document, age), float(value)

"""Escape syntax, with habituation to repeated escape spellings.

Negative responses mark TeX function names, escaped closing delimiters and
literal dollar signs. Hexadecimal/Unicode escape prefixes and horizontal
spacing commands tend positive. Ordinary text stays near zero. Repeated
spellings of an escape usually have a smaller response; escaped dollar
signs also have a stronger response near the document start. Byte fragments of
Greek, Latin, Devanagari and Arabic-form characters can respond positively
at incomplete UTF-8 token boundaries. This approximates structured-text
spikes, leaving weak word-specific background and initial-token quirks out.
"""

READS = ()
TRIG = frozenset('sin cos tan cot sec csc sinh cosh tanh'.split())
LIMITS = frozenset('lim min max inf sup arg'.split())
FUNCTIONS = frozenset('exp log ln det dim deg gcd'.split())


def response(b, previous, repetitions, position=512):
    s = b.decode('utf-8', 'replace')
    if previous == b'lim' and s in ('inf', 'sup'):
        return -4.0  # The second part of liminf/limsup.
    if previous == b'\\t' and s == 'anh':
        return -3.5  # The rest of the hyperbolic tangent command.
    # Two backslashes are a line break, not an escape for the next token.
    trailing = len(previous) - len(previous.rstrip(b'\\'))
    if trailing % 2:
        if s in TRIG:
            return -1.4
        if s in LIMITS:
            return -2.5
        if s in FUNCTIONS:
            return -1.7
        if s == 'var':  # Prefix of variant Greek-letter names, e.g. varphi.
            return -1.35
        if s == 'prod':
            return -1.1
        if s == 'begin':
            return -0.3 - 0.3 / (1 + repetitions)
        if s.startswith('}'):
            extra = 0 if s.startswith('}_') else len(s) - 1
            return -3.0 / (1 + 0.65 * extra)
        if s.startswith('|'):
            return -2.7
        if s.startswith('{'):
            return -0.7
        if s.startswith('$') or s.endswith('$'):
            return -3.8 if previous.startswith(b'}') else -1.5
        if s.startswith(','):
            return -1.3 if '\\' in s else -0.15
        if s in ('hs', 'vs'):  # Beginnings of hspace/vspace.
            return 1.9
        if s == 'h':
            return 0.5
        if s == 'phant':
            return 1.0
        if s == 'xe':
            return 1.9 + 1.0 / (1 + 0.8 * repetitions)
        if s == 'xc':
            return 0.8
        if s == 'u':
            return 2.5
        if s == 'x':
            return 0.4
        if s.startswith('!'):  # TeX negative thin space, possibly before '='.
            return 3.8 if s.startswith('!=') else 1.4
        if s in ('#', '%', '_'):
            return -1.0
    if '\\$' in s:
        if s.startswith(' '):
            value = (-0.05 - 2.5 / (1 + 0.4 * repetitions)
                     - 2.6 / (1 + position / 5))
            if previous.strip() in (b'=', b'=='):
                value -= 1.2
            return value
        return -0.25 - 0.7 / (1 + repetitions)
    if s == '\\xe':
        return 0.3 + 1.3 / (1 + 0.8 * repetitions)
    if s == '\\xc':
        return 0.1
    if s == '\\xa':
        return 0.05 + 0.35 / (1 + 0.1 * repetitions)
    if s == '\\x':
        return 0.15
    if s == '\\u':
        return 0.7
    if '\\_' in s:
        return -0.5
    # Prefix bytes of partially tokenized Unicode characters.
    if b == b'\xe0\xa4':  # Devanagari.
        return 3.5
    if previous.endswith(b'\xef'):
        if b == b'\xba':  # Arabic Presentation Forms-B.
            return 3.2
        if b == b'\xbb':
            return 2.3
    if b == b'\xb8' and previous.endswith(b'\xe1'):
        return 1.6  # Latin Extended Additional.
    # E1 BC begins the UTF-8 encoding of the Greek Extended block.
    if b == b'\xbc' and previous.endswith(b'\xe1'):
        return 1.1
    if b == b'\xc2':  # First byte of Latin-1 supplement characters.
        return 0.3
    return -0.002


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, counts, position = b'', {}, 0
    else:
        _, previous, counts, position = carry
    b = prefix.token_bytes[-1]
    n = counts.get(b, 0)
    value = response(b, previous, n, position)
    counts[b] = n + 1
    return (doc, b, counts, position + 1), value

"""Quote boundaries, with smaller responses to inline-code and math delimiters.

Guess opening versus closing from surrounding punctuation and the most recent
marker of the same kind. Openings are positive; closings usually negative,
especially a space followed by a closing quote in a short quotation. Attached
punctuation and escapes modify the response. This is a heuristic lexer, not a full
parser. Ordinary tokens are zero and word-internal apostrophes are weakly positive.
"""
import math

READS = ()
# Each familiar delimiter family has an opening and a closing response.
DELIMITERS = {
    'double': ('"', 1.40, -0.83),
    'single': ("'", 1.39, -0.59),
    'curly': ('“”„', 1.15, -0.75),
    'curly_single': ('‘’‚', 1.04, -0.33),
    'angle': ('«»‹›', 1.26, -0.58),
    'cjk': ('「」『』', 1.15, -1.05),
    'code': ('`', 0.67, -0.64),
    'math': ('$', 0.60, -0.44),
    'italic': ('*_', 0.09, 0.03),
    'bold': ('', 0.81, -0.94),
}
FAMILY = {c: name for name, (chars, _, _) in DELIMITERS.items() for c in chars}


def estimate(carry, token, doc, position):
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', {}, 0)
    _, tail, previous, last, line = carry
    s = token
    next_line = line + s.count('\n') + s.count('\\n')
    carry = (doc, (tail + s)[-80:], s, last, next_line)
    marks = [(i, c) for i, c in enumerate(s) if c in FAMILY]
    if not marks:
        return carry, 0.0
    quotes = [(i, c) for i, c in marks if c not in '*_$`']
    i, mark = (quotes or marks)[0]
    family = FAMILY[mark]
    left, right = s[:i], s[i + 1:]
    context = tail + left
    escapes = len(context) - len(context.rstrip('\\'))
    before = context.rstrip('\\')[-1:]
    if mark in "'’" and before.isalpha() and right[:1].isalpha():
        return carry, 0.07
    count = sum(c == mark for _, c in marks)
    if mark in '*_':
        if s.strip() not in (mark, mark * 2) or right.isspace():
            return carry, 0.0
        family = 'bold' if count == 2 else 'italic'
    key = (family, escapes % 2)
    old_pos, old_open, old_line = last.get(key, (-1000, False, -1))
    distance = max(1, position - old_pos)
    event_line = line + left.count('\n') + left.count('\\n')
    inside = old_open and distance < 100 and (
        old_line == event_line or not left or not left[-1].isspace())
    opening = not before or before.isspace() or before in '([{=:,+><'
    suffix_closes = right and (right[0].isspace() or right[0] in ',:;.)]}')
    if suffix_closes and not left.strip(' \\') and (
            inside or not opening or not before or '\n' in right):
        opening = False
    elif inside and mark not in '”’»›」』' and not right[:1].isalnum():
        opening = False
    elif mark in '“‘«‹「『„‚':
        opening = True
    elif mark in '”’»›」』':
        opening = False
    elif right[:1].isalnum():
        opening = True
    last[key] = (position, old_open if count % 2 == 0 else opening, event_line)
    if count > 1 and mark not in '*_':
        return carry, -0.08 if opening else -0.18
    value = DELIMITERS[family][1 if opening else 2]
    if opening:
        if previous.rstrip().endswith(':'):
            value += 0.26
        if previous.rstrip().endswith(','):
            value += 0.22
        if left and left[-1].isspace():
            value -= 0.04
        if left.rstrip('\\').endswith(('{', '[')):
            value -= 0.27
        if right:
            value -= 0.34
    else:
        if right:
            value += 0.91
            if right.startswith('\\'):
                value -= 1.72
        if left and left[-1] not in '\\ \t\n':
            value -= 0.13
        if mark not in '*_$`' and left and left[-1].isspace():
            value -= 0.87
            if not right:
                value += 0.94 - 3.99 / math.sqrt(distance)
                if previous.rstrip().endswith((':', '=', ',')):
                    value -= 1.51
        if mark in "\"'" and left.rstrip('\\').endswith(('=', '(', '[', '{')):
            value -= 1.01
            if not right:
                value += 0.23
        if inside:
            value -= 0.42 / math.sqrt(distance)
        if mark in "'’" and previous.isalpha() and len(previous) < 3:
            value -= 0.21
    return carry, float(value)


def step(carry, prefix, upstream):
    return estimate(carry, prefix.token_strings[-1],
                    int(prefix.document_ids[-1]), prefix.position)

