"""Opening vs closing quotation marks (layers.1.mlp.down_proj:6142).

A quote detector with a sign. It is positive on a quotation mark that OPENS a quotation:
' "' (a space, then a quote), '("', '="', ':"', '{"', ' “', ' «', ' ‘', ' 「', and
' \\'' (space then apostrophe). It is negative on a mark that CLOSES one: a bare '"' or
"'" attached to the end of a word or punctuation, a quote that closes a quotation already
open on the same line, and the curly closers ” ’ » 」. Apostrophes inside contractions
('s, 't, ’re) and all other text give 0.

Open or close is read from the text so far:
- a quote right after a space opens, unless a quote of the same kind is still open on
  the line (then it is ambiguous, so 0); a quote right after an opening bracket, '=' or
  ':' always opens;
- a quote attached to a word or punctuation closes if one of its kind is open on the
  line; a backtick or apostrophe attached to something closes regardless;
- when the token also carries punctuation (',"', '".', '":') the response is weak;
- the open state is the parity of same-kind quotes since the last newline, reset per
  document.
"""

CURLY_OPEN = set("“‘«「『《„")
CURLY_CLOSE = set("”’»」』》")
ASCII_QUOTES = set("\"'`$")
OPEN_BEFORE = set(" ([{=:\t")

# Typical activation when a quote of this kind opens (+) or closes (-) a quotation.
OPEN_VALUE = {'"': 1.4, "'": 1.4, "`": 0.4, "$": 0.5}
CLOSE_VALUE = {'"': -1.1, "'": -0.5, "`": -0.7, "$": -0.8}
CURLY_OPEN_VALUE = 1.0
CURLY_CLOSE_VALUE = -0.7

READS = ()


def quote_value(tok, i, inside, prev):
    """Activation of the ASCII quote at tok[i], given whether one of its kind is open."""
    ch = tok[i]
    alone = i == len(tok) - 1 or tok[i + 1:] == "\\"  # the token is just the quote mark
    j = i - 1
    while j >= 0 and tok[j] == "\\":
        j -= 1
    before = tok[j] if j >= 0 else prev[-1:]  # the character before the quote
    if before == " ":
        if inside and ch != "'":
            return 0.0
        return OPEN_VALUE[ch] * (1.0 if alone else 0.5)
    if before in OPEN_BEFORE:
        return OPEN_VALUE[ch] * (1.0 if alone else 0.5)
    if inside or ch in "'`":
        return CLOSE_VALUE[ch] * (1.0 if alone else 0.15)
    return 0.0


def step(carry, prefix, upstream):
    new_doc = prefix.position == 0 or prefix.document_ids[-2] != prefix.document_ids[-1]
    counts = {} if new_doc or carry is None else dict(carry)  # open-quote parity per kind
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if prefix.position > 0 and not new_doc else ""
    if "\n" in tok:
        counts = {}
    for i, ch in enumerate(tok):
        if ch in "'’" and tok[i + 1:i + 2].isalpha():
            return counts, 0.0  # apostrophe in a contraction such as 's
        if ch in CURLY_OPEN:
            return counts, CURLY_OPEN_VALUE
        if ch in CURLY_CLOSE:
            return counts, CURLY_CLOSE_VALUE
        if ch in ASCII_QUOTES:
            inside = counts.get(ch, 0) % 2 == 1
            counts[ch] = counts.get(ch, 0) + 1
            return counts, quote_value(tok, i, inside, prev)
    return counts, 0.0

