"""A partial explanation: negative responses to p/pa-like written fragments.

Use pinyin and transliteration, weaken whole-word matches, and recognize a
short vowel after a separate p. Recent Vietnamese spelling marks select ph
readings. Join split UTF-8 characters and reset state at document boundaries.
Repeated middle dots receive a separate small positive value. The strengths
are approximate; this does not explain most token-specific variation.
"""
import codecs
import re
from functools import lru_cache

import regex
from anyascii import anyascii
from pypinyin import lazy_pinyin, Style

READS = ()
HAN = regex.compile(r'\p{Han}')
KOREAN = regex.compile(r'\p{Hangul}')
KANA = regex.compile(r'[\p{Hiragana}\p{Katakana}]')
PINYIN = {
    'pa4': -2.10, 'pai4': -3.80, 'po4': -1.13,
    'pan4': -.31, 'pei4': -.23, 'pang2': -.66,
}
AFTER_P_A = {'Latin': -.57, 'Cyrillic': -.90, 'Greek': -1.44}
VIET_PH = {'phai': -3.32, 'phat': -2.14, 'pha': -2.48}


@lru_cache(maxsize=16384)
def describe(text):
    word = text.strip()
    roman = anyascii(word).lower()
    script = ('Greek' if regex.search(r'\p{Greek}', word) else
              'Cyrillic' if regex.search(r'\p{Cyrillic}', word) else 'Latin')
    vietnamese = any(c.lower() in 'ăâêôơưđ' or '\u1ea0' <= c <= '\u1ef9'
                     for c in word)
    value = 0.0
    chars = HAN.findall(word)
    if chars:
        for j, syllable in enumerate(lazy_pinyin(''.join(chars), style=Style.TONE3)):
            strength = PINYIN.get(syllable, 0.0) - .07 * syllable.startswith('p')
            dilution = len(chars) ** -.65 if j == 0 else .3 / j ** .5
            value += strength * dilution
    elif word and KOREAN.fullmatch(word[0]):
        syllable = anyascii(word[0]).lower()
        onset = re.match(r'p(ae|a|u)', syllable)
        if onset:
            value = (-2.56 if onset.end() == len(syllable) else -.31)
            value /= len(word) ** 2
    elif word and KANA.fullmatch(word[0]) and roman.startswith('p'):
        value = -.30 / len(word) ** 2
    elif roman in ('pa', 'pai'):
        value = -.17 if roman == 'pa' else -2.07
    elif re.fullmatch(r'(p[au]+){2,}', roman):
        value = -1.56
    elif len(word) > 1 and set(word) == {'·'}:
        value = .37
    return value, roman, script, vietnamese


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, b'', '', 0)
    _, pending, previous, vietnamese_age = carry
    data = pending + prefix.token_bytes[-1]
    text, consumed = codecs.utf_8_decode(data, 'replace', False)
    pending = data[consumed:]
    value, roman, _, vietnamese = describe(text)
    _, prior_roman, prior_script, _ = describe(previous)
    value += .002
    continuation = bool(text and text[0].isalpha())
    shortness = (1.0 if re.fullmatch(r'[aeiou]+', roman)
                 else 1.0 / max(1, len(roman)) ** 1.5)
    if continuation and prior_roman.endswith('p') and roman:
        vowel = roman[0]
        if vowel == 'a':
            value += AFTER_P_A[prior_script] * shortness
        elif vowel == 'e':
            value += (-1.08 if prior_script == 'Greek' else -.24) * shortness
        elif vowel == 'u':
            value -= .34 * shortness
    if vietnamese or vietnamese_age:
        if roman.lstrip('-_') == 'ph':
            value -= 3.47
        elif roman.startswith('ph'):
            value += VIET_PH.get(roman, -.40)
        if continuation and prior_roman.endswith('ph') and roman.startswith('a'):
            value -= 3.45 / len(roman) ** 1.5
    vietnamese_age = 30 if vietnamese else max(0, vietnamese_age - 1)
    return (doc, pending, text, vietnamese_age), float(value)
